insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "98af9b34-e893-41c8-a106-372990cbe917", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 10, "content": "Cole Heilborn (00:20:06): Interesting. When you say wireframe, you're talking about the layout of the website page?\n\nChris Dickerson (00:20:10): That's right. And all the content holes that you need to fill on your website, and then we expand that out.\n\nCole Heilborn (00:20:18): Okay. So coming back to the Hydro Flask example, when you were wire framing out the website and identifying the pieces of content that you needed, I dunno, give us an idea of what were some of those pieces that you identified were crucial for this product page?\n\nChris Dickerson (00:20:33): So product detail images, we wanted them shot on white, but then we also wanted to be able to demonstrate it in environment.\n\nCole Heilborn (00:20:43): Why is that", "token_estimate": 184, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:20:06", "end_timestamp": "00:20:43", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "41a293f4-b29d-482e-aa55-edaffa9bc1b4", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 11, "content": "Chris Dickerson (00:20:45): Just so people can see doing that activity. So whether it's like you're in a hammock drinking a beer, or you're on the beach or you're at the trailhead or you're mountain biking, there's several different use cases for it that you can give people ideas. And some brands have done a really good job at integrating user generated content on their product detail page. One of our clients, MSR, on their product detail pages, they'll allow people to upload their images, which is actually pretty cool because they're obviously all approved and reviewed. But I mean, even on Amazon, that's one of the first things I do when I buy something on Amazon is I actually look at the images that the customers have uploaded because there's a little bit more trust with that. And I think that's kind of a really interesting niche that you can look at as part of your activation plan. (00:21:50): And so when you're thinking about putting up lifestyle images on your product detail page or throughout your website or your landing page, can you get user generated content ahead of time? And that just adds more trust to the whole process. Sometimes you can seed your influencers and ambassadors with product to have them, and that's something we've done in the past. I'm pretty sure Hydro Flask did that as well, would see product out to people who they trust and say, Hey, will you review this? Will you take photos of this? And then you actually have people talking about it and uploading, and then you've got sort of other use cases. So again, it's like looking at when that consumer's on your product detail page or your landing page, can they see themselves using this in a cool way that they might've ever thought? Never thought? (00:22:52): And when you look at another sort of thing to think about that a lot of marketers haven't thought about is bipoc activation and different communities will use your product differently, and usually we'll just go to who we know and who our friends are. And especially in outdoor where we go mountain biking or whatever, and we all do the same thing the same way in other communities. It's really important to understand how those communities are using your products. And it's also pretty untapped right now, outdoor research and Scarpa have done a pretty cool job of launching some new programs that really bring in bipoc voices into their marketing and into their campaigns and into their product development. And they've learned a ton about how others are using their products and they're integrating them into their marketing channels right now. So that's sort of a newer part of a go-to market strategy is how are you including Bipoc communities within your marketing and product development. And so that could be really interesting to reach out to those communities. And if you're seeding product, okay, how are they using it differently from how my friends use that product? (00:24:22): Something great to think about with that content strategy.", "token_estimate": 753, "speakers": ["Chris Dickerson"], "start_timestamp": "00:20:45", "end_timestamp": "00:20:45", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "5bd0dbd6-fe77-4b01-9572-200f65f695f9", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 12, "content": "Cole Heilborn (00:24:26): So is that, thinking about your comment about AB testing, are brands out of place, is this something that people try to do where they look at the different communities that are using their products and then they build out tailored custom product pages for each of those communities so that through the different channels they end up on the page that best reflects them? Is that a thing?\n\nChris Dickerson (00:24:53): I don't know if it's that specific, (00:24:56): But usage could be very intentional and specific. So if you're an RV company and you sell a towable camper, you could build a product detail page for Subaru owners and Toyota Tacoma owners, lake campers and ocean campers and surfers. That would be a really good use case landing page. And if you're selling this tow bowl and you're looking for a camper that is great for surfing and going to the ocean on the beach and then you're looking for, okay, I want a surf camper, you would probably rank pretty high for that if you brought up those product detail pages or those landing pages and then those can all connect the dots.\n\nCole Heilborn (00:25:51): Interesting.", "token_estimate": 289, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:24:26", "end_timestamp": "00:25:51", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "a9b66f21-19c0-4ef6-9188-06dd72e41621", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 13, "content": "Chris Dickerson (00:25:52): That is something that we absolutely help clients build and do, and we find it pretty effective and a lot of companies won't do it, but if you just start small, that's also a really good thing to do. Just pick out three a client we've got right now called life handle, which is this harness that helps distribute the weight to carry your kid or luggage or a bike or a paddleboard, or you can carry a Yeti cooler with this thing that's fully loaded by yourself because the way it distributes the weight. So they're just launching right now, and we're in the process of building these pages for them to be like, okay, here's for the pet owner, here's the leash, here's if you've got kids and you're going to Disneyland on vacation and here's how you carry a paddleboard. And so we're building out these use cases that not only can we target these niche audiences, so like dog owners, parents stand up, paddle board owners, we can build these landing pages that will compete pretty highly in search and then we can build ad campaigns, mini ad campaigns around all of those landing pages. So that sort of expands the scope even more.\n\nCole Heilborn (00:27:15): But if I just go to their homepage and I find that product page, if you have all these sub product pages based on specific user groups, and I don't come through one of those channels, is there a hero product page that is kind of a catchall for everyone?", "token_estimate": 360, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:25:52", "end_timestamp": "00:27:15", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "de63f19b-6ee9-4d0b-b45b-dec9f3141525", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 14, "content": "Chris Dickerson (00:27:32): It depends on how you position it. Oftentimes those landing pages will be hidden and they'll just be traffic driving or traffic generating pages, so there might not anything be linking to them. So aside, they would link to the product detail page, you want all the links going back to that product detail page ultimately. So that's one way you can do it and just keep it really tight and almost hidden as a way to target people or you can turn it into more of a community aspect. So if you've got a fun product with multiple uses, or I'll go back to that RV camping one, you could turn it into a content hub and sort of back into it. So if you have an ambassador and influencer out there camping, there's no reason they can't write a blog post on their story as long as you're planning out what the keywords are that you want them to hit to be like, okay, I want you to take my product to the beach and I want you to go surfing and then use these keywords and link to this page or take the photos, take the videos and we'll write it. (00:28:55): And then you can have it a different way where you can make complimentary content that isn't salesy, but it'll show you what the purpose is. But at the same time, you're actually just looking at this cool adventure at Evo, one tactic we would use would build a guide like a how to wax your skis or how to tow a wake border, and that would be sort of our main guide, which a lot of big e-commerce specialty retailers now, everybody has lots of guides. There's a very specific reason it drives a ton of organic traffic. So they technically traditionally don't convert that high, but you're getting a lot of traffic at your website and then you're getting them in your system and down the funnel. Now, we would always follow that up with a blog post or an interview where we would go out and interview maybe somebody from Swix to or an Olympian who waxes their skis. (00:30:02): I think we had Ryan Sheckler, I think he was at one of the Evo stores once for a big skull candy, big event, red Bull event, and we had Sheckler putting a skateboard together. I think he did how to do grip tape or how to put down grip tape. So we were able to have some photos of him doing that. We wrote an article, I think we got a couple quotes, and that was kind of cool. We did stuff with the Northwest Avalanche Center. We can get some experts to talk about avalanche safety. We've got avalanche safety guide. Oh, by the way, we've got all these avalanche safety products. So it all really fits together a nice little ecosystem.", "token_estimate": 646, "speakers": ["Chris Dickerson"], "start_timestamp": "00:27:32", "end_timestamp": "00:27:32", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "f72f2f1a-8cdf-41ac-8cad-301b130e522c", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 15, "content": "Cole Heilborn (00:30:48): Sure. So all of this though, all these examples, these are things that you planned out six months a year in advance. Is that the idea?\n\nChris Dickerson (00:30:58): Yeah. Yeah. You try to and you have to complete all the work, but it's really good when you're building your master comms calendar and marketing calendar that, I mean, it doesn't have to be super in depth. It can just be a spreadsheet with okay, homepage, email marketing, Instagram, TikTok, and just work your way down every single one of your channels and how you're activating it. And when you're planning to activate it, then you can understand, okay, I need to tell my social media team, this is coming down the pipeline. We're planning to activate it this month for six weeks. What do you suggest? And then they can build that plan, working off that positioning statement, working off of everything else they know and the knowledge to figure out, okay, what am I going to do? What's my fun little marketing take on that? And then, okay, what assets do I need from that?\n\nCole Heilborn (00:32:02): So go ahead.\n\nChris Dickerson (00:32:04): No, go ahead.\n\nCole Heilborn (00:32:05): So with all this, how do you make sure that this connects to your brand and fits within the brand? Because talking about potentially a lot of content and like a spiderweb going everywhere, how do you make sure that every piece is authentic to the brand?", "token_estimate": 358, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:30:48", "end_timestamp": "00:32:05", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "c7d321a3-db87-403d-835e-1b09bfcf9d62", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 16, "content": "Chris Dickerson (00:32:25): Well then I think it falls back onto the brand manager or who's ever really that stake in the sand your North star for your brand. And I think that's really important. Once you understand which channels you want to activate and then you've planned out the timing on that, then you get a really good idea of the assets that you need, then I think you can really start to plan what that higher level overarching marketing campaign is. And that's where you can bring it all together. And when you've got your brand manager or whoever's the stakeholder in that to be like, okay, all my teams have communicated what they need their wishlist. Let's work with our photographer and videographer to put together a plan on here's our overall story and message. Here's who we want to talk to and here's all the assets we need. And then that's where I think it can be really fun working with the photographer and videographer. And I'd like to hear your thoughts on when a client comes to you, what are your questions? You're asking them to make sure that you're fulfilling. You don't want to provide them with a video or photos that don't hit everything for them, or you also want to anticipate what they're going to need because it kind of sucks to be like, call the videographer a month later, go, oh, I totally forgot I need this. You're like, well,\n\nCole Heilborn (00:33:58): Yeah, that's no good for anyone.\n\nChris Dickerson (00:34:00): No, exactly. So being able to anticipate working from an agency side, and I'm sure you can relate, we have to anticipate and be sort of look around the corner on what we know they're going to need, but they don't know they need yet or remind them like, oh, hey, by the way, have you thought about this?\n\nSpeaker 5 (00:34:19): Sure.\n\nChris Dickerson (00:34:19): And ideally putting together that big really comprehensive plan for big product launch will help them peek around the corner and take the blinders off. But I think that's our jobs as agencies to really help unlock that for them.", "token_estimate": 512, "speakers": ["Chris Dickerson", "Cole Heilborn", "Speaker 5"], "start_timestamp": "00:32:25", "end_timestamp": "00:34:19", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "dae9a4bf-0403-47f3-9189-f6dbee332d3e", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 17, "content": "Cole Heilborn (00:34:32): Yeah, I feel like, well, I guess do you see a lot of folks just kind of skipping ahead to the visual stuff, which I would argue is the most fun stuff, but you would probably argue is maybe even the least, not the least important, but it's so far down the pipeline that either you have to have all your other ducks in a row before you can even begin to think about that stuff.\n\nChris Dickerson (00:34:54): I think So it's incredibly important, but you're going to get a better product that's more cohesive if you do sort of the less sexy stuff first.\n\nCole Heilborn (00:35:06): Yeah, all the Excel work.\n\nChris Dickerson (00:35:09): Yeah, yeah, the nerd stuff, but it's rooted in words and something about writing it all out from a storytelling point of view and a tactical point of view really for me, and I'd say many others, it really helps it coalesce into what you need. And then that makes the creative part just so much more fun and in my mind, more collaborative and creative. Oftentimes, I've worked with several creative agencies and I often found the clients that said, oh, we're launching a new product. Go do something for me. Those are often the hardest projects to think about because you've got no guardrails. So having a little bit of a plan in place will help sort of narrow in your thinking to really spur some topics and ideas. And I always find putting guardrails on designers and creatives actually, even though it might be a little bit harder for them at first, I find them coming back with so much creativity and really, really good ideas that are just so on target to what the brand is looking for in giving you a heads up on, okay, I need all of these assets. Because if you're thinking about all the fun stuff first, like we were saying, you're going to come back a month, six weeks down the road and be like, oh, I really need this. And it doesn't really often fit in to the whole campaign. You can totally tell it's been piecemealed on after the fact because they're like, oh, crap, I forgot this. And yeah, that does happen. That's always going to happen, but you can sort of mitigate that ahead of time. That will give you a better product.", "token_estimate": 549, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:34:32", "end_timestamp": "00:35:09", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "6310d5ac-ae5d-4b58-a623-c9993307a530", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 18, "content": "Cole Heilborn (00:37:08): Well, I feel like by adding guardrails, you then set up the creative team or individual, they know what you need, and now they're no longer guessing What do I need? Now they're thinking about, okay, how do we do it and how do we do it really well? Then the question becomes what do they need? And we're guessing what type of project or assets they could use, but now it's like, okay, we know that now we can spend our energy actually making the thing that's going to look really well or speak really well to the brand or highlight these specific features.\n\nChris Dickerson (00:37:43): And I think it gives the brand more confidence in your abilities because if you're a creative agency or a PR firm or anybody that's coming up with ideas, if you're not giving them any guardrails or something to go on and you just tell them Go wild, oftentimes they will come back with the most random off brand things and you're like, what on earth is this? And you're just like, if I have four ideas, they're going to be four totally different ideas with different looks and feel. Or if you would've given them some good creative guidance on the whole marketing plan, you're going to have four good ideas that are actually very close to your brand, the product. So I think you get three to four unique ideas that are winners in their own right and it's really hard to choose versus where did this come from.\n\nCole Heilborn (00:38:47): Well, and that brings up another good question of how do you work with external partners or even internal for that matter, but just different departments as you're bringing this all to fruition. You mentioned earlier that having the timeline is crucial because then you can start to say, okay, I know at this point we're going to be doing these things and we need these people. I guess with your experiences, what have you found to be really effective? When do you bring people into these conversations?\n\nChris Dickerson (00:39:17): I would say having an owner for the project, like one owner, one decision maker.", "token_estimate": 515, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:37:08", "end_timestamp": "00:39:17", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "10d46ab4-9356-4025-abff-3ad581b9b2ad", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 19, "content": "Cole Heilborn (00:39:24): And are they the individual who is also the brand manager who can check everything against the brand, or is this sometimes a different person?\n\nChris Dickerson (00:39:32): It can be either or. Sometimes it's nicer to have one person do the very tactical stuff and ushering through everything, and then you've got the brand manager as that check along the way and usually work pretty closely together. And then as you add more and more people to the conversation, keeping them up to date and informed on what we're doing. But I think having a clear leader is really important when you're rolling these things out and whether that's one or two people working together. I think ultimately having a decision maker, this is yes and no is super important because then you start getting designed by committee and also talking to your team about, and regardless of what you think about Jeff Bezos, one of the things that he always says is that if you come to me with an idea and it's thoughtful and I disagree with it, but ultimately we decide to go ahead with it, I will make sure I'll put my disagreement aside and I will support you fully. (00:40:33): And that's what he expects from the entire team. So whether or not you disagree with something, and I see this happen in brands and outdoor a lot, so passionate about their product and what they do and what we think is the best way forward, and I've been guilty of this too. We always think where this is the right path to go on. And it's something that you learn over time is, okay, I've voiced my opinion and it's not resonating. I didn't convince them, and they're going to go this way. That's fine. And just support it and make it success. Because if it's fully successful and you're fully supporting it, that's really what's going to make a difference. If you disagree with something and you're just always writing on that disagreement, it is just going to be a bit of a junk show. So by having that one decision maker that, okay, this is the person that sets the tone and I will hear you and I'll incorporate your feedback and I value it, but this is the way we're moving and let's jump on board. (00:41:46): Because again, it goes back to like, okay, then you work that back into your channel. So I'd say everybody understands what the launch is, what the positioning is, go back, manage their channels, see what they need, and then start getting feedback in and then working on that. So I think what you can do when you bring in partners, once something's coming to market, it's probably okay to let all your partners know just like, Hey, this is coming out of the pipeline in six months to a year. I find that really helpful from a PR perspective because then we can start identifying target markets for that product and look at emerging trends. I mean, search is such a big part of what we do and how we do it, and if we know Scarpa calls their climbing shoes, rock shoes, (00:42:42): But that's a very niche term. It's like a very core climbing term, but if you're a new climber, you're probably going to Google climbing shoes or rock climbing shoes. So it's very important to us when they're launching a brand new entry level climbing shoe, we probably want to make sure that we're including some of these key phrases in there. And that's really important to us. We can take that back to say Scarpa and say, oh, by the way, more entry level climbers actually Google climbing shoes versus rock shoes. So when you're building out that campaign, we want to make sure that, are you showing those entry level climbers in a cool way? Are you using these words here and there? Yes or no? Maybe they don't even want to do that. They just want to stay super core and that's totally reasonable. But that's good for us to know too when we go out and pitch so we can sort of start formulating a plan based upon their direction, but we provided them some feedback and ideas on what we're seeing from the media and what they're talking about.", "token_estimate": 1004, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:39:24", "end_timestamp": "00:39:32", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "4d8199aa-984a-4a12-b54f-a61d023fad51", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 20, "content": "Cole Heilborn (00:43:44): Okay, we've got our plan, we've got our master plan, the product detail page is in ship shape order. We've got all of our assets ready to go. Now we're looking at our execution on our channels, whether that's social email, YouTube, I don't know all of 'em. How is that happening? Are you identifying goals for each of those channels with timelines attached to those goals? How does that work?\n\nChris Dickerson (00:44:15): Yeah, I usually like to look if it's a demand generation or demand capture channel. So demand generation would be more of awareness stuff. We want to make sure that this channel is just eyeballs impressions, and then demand capture would be basically more of the paid stuff or so really close to conversion, lower in the funnel and identifying, okay, if we know Facebook, we're never going to make a sale off of Facebook, but it's a pretty cheap way to get a million impressions. Okay, what's next? From there, then we can say, okay, I want to make sure I've got a million impressions on Facebook and on Instagram, and we're not worried about getting site traffic. So I think those are good goals that each one of your team members can come back with. Okay, do we think this channel will drive sales yes or no? If it's no, what can it do for us? If it's yes, how do we do that? And then so look at that in that way. You're not disappointed when you only get a hundred dollars of sales from Facebook, but in the whole click path, Facebook might've attributed to the awareness of that product and the whole what do you have to show somebody something seven times where they purchase or something like that, whatever changes every day, whoever you're reading. But it's like that reinforcing sort of thing. I think that's really important to look at. (00:46:00): And again, it doesn't have to be overly complicated or super granular. It can just be like, my goal here is to get video views and that will be awesome if we get video views and that could be a success because I don't think it needs to be all tied to revenue because once you tie everything back directly to revenue, you start to commoditize your brand and you lose some of the brand and the fun of it all and why people are really engaging with your content in the long term.", "token_estimate": 571, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:43:44", "end_timestamp": "00:44:15", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "1b10fd2b-2a0c-40af-8e87-bb43cfdd45d1", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 21, "content": "Cole Heilborn (00:46:30): How important are endemic sites and resources when you're considering the execution of the campaign?\n\nChris Dickerson (00:46:38): I think they're pretty important these days when we've got so much information out there and it's really hard to know who to trust. I mean, even reviews, lots of 'em are fake reviews. So I am skeptical of reviews now, and if I don't know who to trust, there are some publications that I still do trust. A lot of them are pretty honest about whether or not they got the product for free, whether or not it's an affiliate link that they're going to make a commission off of. (00:47:14): And just putting those little things in there as driven, that third party validation and third party trust around different products. So I think it is pretty important these days because what's the first thing you do when you find a product that is, if it's a highly considered purchase, you're going to do your research and you're going to read lots of stuff and you're going to read it from the experts. So if you're buying a pair of skis, you're going to go to evo, you're probably going to go to the brand page, you're going to go to blister review, you're going to find all the information out there outside to really make that, and then you'll probably find some comments on TGR forums, go down the rabbit hole. But all of those little points are going to help you make your decisions. So I think it is really important to be there.", "token_estimate": 370, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:46:30", "end_timestamp": "00:46:38", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "b0d12a5e-3073-461e-aeb3-1911dd87989a", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 22, "content": "Cole Heilborn (00:48:06): Yeah, as you're talking, I just keep mean, I'm kind of getting overwhelmed just thinking about all of just how big this whole thing can get. Obviously you could go as big as you want or as small as you want. And I guess the only thing that's probably the deciding factor is capacity and budget for folks who are just trying to bring, they're a small company and they're just trying to bring one product to market and they're listening to this and they're like, oh my gosh, I can't do all of this. I made this thing. I run the business. I do everything by myself. What are some of the most important things to focus on? I don't know. Most bang for your buck if you're going to spend your time and what money you do have, where should people focus that?\n\nChris Dickerson (00:48:59): Yeah, I would want to make sure that you've done a little bit of keyword planning around the product and just making sure you're checking the boxes from an SEO point of view and then work your way out from there. And there's plenty of templates out there on how do you name your page, what should the URL be? What should your title be and what should the copy be? So I think if you can start there with really strong basics and then understand the type of content that you need to support that. So you need good copy, good images and good videos. So knowing that you're like, okay, I've got that. You build your little deck of your features and benefits and position your overt benefit and then just list out the channels that you want to activate. So I think that's really important to keep it really nice and succinct. And again, the larger the team, the more comprehensive this can be. I mean, I've seen a go-to market plan from Eddie Bauer years ago that was printed out. It was like six feet tall. I mean, it was crazy. Geez.\n\nSpeaker 3 (00:50:18): Wow.", "token_estimate": 467, "speakers": ["Cole Heilborn", "Chris Dickerson", "Speaker 3"], "start_timestamp": "00:48:06", "end_timestamp": "00:50:18", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "113595c9-9e9e-4674-aa80-ce5cb5b864b2", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 23, "content": "Chris Dickerson (00:50:18): But I mean, they are a massive company, right, with a lot to think about. So not every company needs that. And I think understanding, okay, when I go back to my video and photographer, just got to remind them that, okay, I need short clips for Instagram. I need good photos for Instagram. I need a good hero image for my homepage that I can put copy on. So when you're out there shooting, make sure there's some blue sky in the background where I can write copy on or something along those lines. So just think about the basics of what you need to fill out your content. And I think once you get those basics down, then you can really start going into some tactical approaches to that. So you don't want to be super overwhelmed. I totally hear that. (00:51:23): But again, also understand a little bit of financial planning and demand planning is also really important. And if you want have a good solid grasp and understanding of the numbers is super important as well, because if you think you're going to sell a million dollars your first year of business, that is a unicorn that never happens. So understand, if you want a million dollars in sales, you're probably going to have to have three to $4 million in inventory to reach that turn rate of inventory and everything like that. So set your expectations appropriately with what on your standards. And then I think you can kind of keep it within your budget. So if you think you're going to do $200,000 your first year, okay, that's X amount of dollars per month, what do I need to do that? And then you can really back into, okay, if I am getting $200,000 first year, I'm probably spending 10% of my dollars on marketing. (00:52:28): So I've got $20,000 to spend this year on marketing. How do I do that? What do I spend it on? And I think if you kind of go that route and kind of back your way into some budget dollars, you can really see what you've got to spend. You can understand that the content creators you work with can work within that price. Some can, some won't, and that's okay. That will always sort of shift and change as you go along. So really starting, okay, what's my marketing budget? And then look at the C channels you really want to activate and then build that plan based upon that.", "token_estimate": 573, "speakers": ["Chris Dickerson"], "start_timestamp": "00:50:18", "end_timestamp": "00:50:18", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "27946c35-8168-4074-81a6-d06586df331c", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 24, "content": "Cole Heilborn (00:53:06): Sure. Interesting. So for folks who are on the other side of that and they've got the team and they've got various partners, perhaps yourself, what, I dunno what's up and coming, what's the newest tool? What's the newest gizmo or gadget that you have your eye on that could be really interesting but maybe is on the fringe right now\n\nChris Dickerson (00:53:30): As far as technology goes or product\n\nCole Heilborn (00:53:32): Technology, best practices? I don't know, just anything like that.\n\nChris Dickerson (00:53:38): I still think video is so underutilized and overlooked by a lot of brands and to do it effectively, we can get a good brand video, which is fine, but the product uses videos I think are still lacking. And intent of channel I think is also really important and overlooked. When you look at why somebody is on Instagram, it's probably not to be sold to, it's probably because waiting for a bus or something like that or driving to the mountain, they're not driving though. So I think looking at the intent of channel is really important. You're going to get the most organic reach that way. Also, you're sort of playing into, okay, what's new feature? New feature? What are you doing looking at YouTube where number two search engine in the world is YouTube, what do people go to YouTube for? It's mostly like how-to videos. Obviously if you're younger you're using in a totally different way from older people, but really you go to find out product reviews or how tos. So when you're thinking about intent of channel, how do I want my product to be featured and basically upleveled thinking about that sort of thing. (00:55:09): So when I would look at a go-to-market plan now I want to make sure that if it's a product that isn't like an instant get, probably going to need a lot of video content around what it is, how to use it, why it's for you. And I think that's really important to look at that.\n\nCole Heilborn (00:55:29): So you still see that as being one of the more important pieces, even though I feel like that's been around for a while. Everyone knows that video is important,", "token_estimate": 535, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:53:06", "end_timestamp": "00:55:29", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "e5eee217-f50c-47bd-89ab-861d55b54d3c", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 25, "content": "But people still don't do it. (00:55:43): I've been going to social media conferences for several years and every year it's like, this is the year of video and people, it might change now that everybody's more used to being on camera. I think a lot of people are less hesitant to be on camera because even brand managers or CEOs or founders, some just don't like to be on camera. But I think that's sort of going away where they're okay to talk about their product. So again, yeah, I think it's often overlooked when we ask for video assets for clients. It's getting better now, but still if we need a video for media that shows how to use your product in 30 seconds, can you give me that? And like, well, we don't have that. I run into that a ton. So it's still an issue. (00:56:40): I think understanding that's super important. I think the other thing is humanizing your brand is becoming, it's really, really important these days. Again, it kind of goes back to all those fake reviews and knockoff products that are just flooding Amazon that are just garbage that look really close to your product. And I think that's where your brand and humanization comes in. There's this guy, his name's Mark Schafer, and he is a professor and a social media sort of guru guy. And I've listened to him and speak a couple times and he was actually on Kristen's podcast a year or two ago, but he wrote a book called The Third Rebellion and it was all about humanizing your brand. And he used the North Face as an example at a keynote speak at a keynote he was speaking at. And I thought it was super interesting that he picked the North Face, couple of their outdoor brands on how brands are humanizing themselves. (00:57:47): And I thought it was super interesting and I went up and talked to him afterwards and read his book and everything and got him on the podcast. And what he said was, I totally agree. And I think outdoor brands do a really good job of humanizing it through athletes, through just behind the scenes type things. I think this is just kind of fun for people to see. And with Instagram stories and Snapchat and other videos being in the moment, and it doesn't have to be super polished, it can be in the moment to get people stoked on something, people really resonate with that sort of thing. And consumers are buying stuff based upon the values of a brand these days, especially the younger you are, the more likely you'll choose to buy a brand because of who's behind it. And so I think that's really important to think about how am I coming across the consumer in that way.", "token_estimate": 647, "speakers": ["But people still don't do it."], "start_timestamp": "00:55:43", "end_timestamp": "00:55:43", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "bdbb7636-9135-41de-9180-996ebfe609cc", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 26, "content": "Cole Heilborn (00:58:50): And do you feel like that's, is that something that you should just consider it holistically or specifically for a go-to-market strategy, you're humanizing of the products or the brand?\n\nChris Dickerson (00:59:00): I think it's more of a brand level type thing. It may not be for all brands also, so you got to make sure it fits in with your brand. So you probably won't want to do that as a one-off, but I would say it'd be more laddered up to the brand\n\nCole Heilborn (00:59:16): Level. What pitfalls do you see a lot of companies make? I consistently, I guess with these types of plans,\n\nChris Dickerson (00:59:32): I would say it can get a bit complicated. And when everybody has a lot going on, when you launch a new product, it's not like your day job stops. So it can be kind of overwhelming. And I think that's why that pre-planning is really important because you're just chugging along and you want to make sure that you're planning for your time appropriately when these new products come out. (01:00:03): And being able to tie it back to that overt benefit. And I think that's where people lose some of the direction and that's why it's really important for that brand manager or who's ever in charge of your North Star, to be able to check in with people and just remind them like, Hey, remember this is the goal of it. And being able to address that and revisit it is really important. Otherwise everybody kind of goes adrift. And I think a strong leader can rally everybody back to that one big idea and that's how you really stay focused.\n\nCole Heilborn (01:00:41): Interesting. So simple, but it's so tough.\n\nChris Dickerson (01:00:44): It's really tough.\n\nCole Heilborn (01:00:47): I've really enjoyed this conversation. I appreciate you taking the time. We we're getting close to the end, but I guess any final thoughts? I know there's a lot more that we could have dove into really deeply on this, I guess anything else you want to leave the audience with?", "token_estimate": 501, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "00:58:50", "end_timestamp": "01:00:47", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "c24921c0-1520-4d19-8240-e269bb09ac17", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 27, "content": "Chris Dickerson (01:01:06): Yeah, I would just say it's just lay it out, just whiteboard it out. I'm a whiteboard type of guy and make it collaborative and just let people know what's going on and bring them into the conversation and just let everybody kind of know what you're doing and how you're doing it inside of your method and your approach. And I think once people sort of understand that on how you're doing a certain launch plan that will help people buy into it and they want to help you succeed and you're helping your whole company succeed and the product succeed. And I think that's a big rallying point. So it's pretty gratifying to see a product launch and be successful, especially knowing how much hard work you put into it and also revisit after the launch what worked and what didn't. And I think having a postmortem is also really important. So yeah, just do the due diligence, plan it out and then execute it.\n\nCole Heilborn (01:02:20): Well said. If folks have questions about anything we talked about or anything we weren't able to get to, can people find you somewhere and bug you or are you trying to stay off the radar?\n\nChris Dickerson (01:02:37): No, they can hit me up. They can shoot me an email, which is my last name, Dickerson, at verde pr.com. And I assume it'll be in the show notes and find me on LinkedIn. All that fun stuff all over the place.\n\nCole Heilborn (01:02:56): Awesome. Are there any other channels that folks should be following? Either yours personally or with Verde?\n\nChris Dickerson (01:03:03): I mean obviously go to Channel Mastery and subscribe to Kristen's podcast, subscribe to your podcast, also click subscribe and rate and review\n\nCole Heilborn (01:03:13): All the things.\n\nChris Dickerson (01:03:14): All the things. Yeah, I think my Instagram's Dicker Graham, if you want to see ski pictures of me touring. Not a whole lot there. Or my Twitter is just me complaining about companies, usually about airlines, but no, no, but all seriously, shoot me an email or that's probably the best way to get in contact with me.", "token_estimate": 520, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "01:01:06", "end_timestamp": "01:03:14", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "4153613d-30fe-4eb4-8088-cda85ee9b473", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 28, "content": "Cole Heilborn (01:03:39): Awesome. Sounds good, Chris. Well thank you again for your time and yeah, I feel like we need to do another two or three of these to continue to dive into this topic. I don't know, I just feel like there's a lot that we could still cover.\n\nChris Dickerson (01:03:54): Yeah, I think so too. I think if your listeners have any more questions or want us to dive in deeper, we could come back in six months and do a deep dive on something else.\n\nCole Heilborn (01:04:04): There you go. There you go folks. Bug Chris, if you want to hear more from 'em. Alright, well thank you again for your time and have a great rest of your day.\n\nChris Dickerson (01:04:14): Cool. Thanks Cole. You too. See you.\n\nCole Heilborn (01:04:17): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 239, "speakers": ["Cole Heilborn", "Chris Dickerson"], "start_timestamp": "01:03:39", "end_timestamp": "01:04:17", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "fb518e77-7d00-47c5-9e68-de37c561a539", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 0, "content": "Rob McSkimming (00:03): I say the other thing that was happening there, as Crankworx became a bigger and bigger beer player on the world stage, we had more and more people coming to Whistler and going, this is a cool thing. How can we learn from it? But then more than going, Hey, could we do one of these at our place? So I guess part of it was we thought it would be an interesting way to continue to promote Whistler and the Whistle Mountain bike Park on the world stage.\n\nCole Heilborn (00:28): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn. Today I'm sitting down with Rob Mc skimming. He's the semi-retired business development for Whistler slash Blackcomb the resort. Rob, how are you?\n\nRob McSkimming (01:11): I'm doing great, Cole. How are you doing?\n\nCole Heilborn (01:13): Doing awesome. Yeah, thanks for joining us today.\n\nRob McSkimming (01:16): Yeah, thanks for the opportunity. I'm looking forward to the chat.\n\nCole Heilborn (01:18): Yeah, so as people probably can guess, you're calling in somewhere from near Whistler, specifically Pemberton, is that right?\n\nRob McSkimming (01:27): Yeah, that's right. Yeah, I moved to Pemberton from Whistler. I lived in Whistler for quite a long time, but moved to Pemberton the last two and a half years.\n\nCole Heilborn (01:35): Is living in Whistler everything? It seems like it could be.", "token_estimate": 484, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "00:03", "end_timestamp": "01:35", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "a56df2ab-4a46-417d-aa3a-a8d247643aa0", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 1, "content": "Rob McSkimming (01:41): Yeah, I think so. I guess depending on what that is, but it is a great place, and I think we were fortunate to move there just as the village was being built and to be in Whistler while all that development and transformation was happening. It was a super exciting place to be, and it is a special place just in terms of its access to the amazing skiing and now mountain biking and all kinds of other outdoor activities, and its proximity to everything else in the area. It's a special spot, for sure.\n\nCole Heilborn (02:19): Yeah. Well, I want to give a quick shout out to David Bergoff from RA for connecting us. If folks haven't listened to his episode, it came out a few months ago. I highly encourage it. We talked about leadership in the marketing department, how to be a leader, but David was kind enough to connect us, Rob, and we got to chatting, and I'm just super excited to dive into story. Our topic for today, we're going to talk in about an event, we're going to talk about Crankworx, which is a pretty phenomenal event that I think a lot of folks are familiar with on this show. Maybe they've been to it, they've probably watched it or at least heard of it. But I'd love to kind of dive into this event. We're going to talk about marketing, we're going to talk about experiential marketing and the intersection between all of these different pieces. But Rob, I'd love to hear a little bit more on your background and your relationship. I guess what was your involvement with Whistler? What was your relationship with Crank Works and how did all that get started?", "token_estimate": 401, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "01:41", "end_timestamp": "02:19", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "493501ae-d578-4598-8a5a-7dc8afe4a404", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 2, "content": "Rob McSkimming (03:18): Yeah, because worked there for so long, it's a bit of a long story, but I'll try to get to the point as quickly as I can. So as I said, I moved there in 19 80, 81. I actually started as a ski instructor, so that was my background on the ski side of things. I claim I was the first ski instructor to actually be hired the year that glaucoma opened. So that's how far back that goes. And then at that time, glaucoma was new on the scene. The resort was just developing summer in the resort was, it was non-existent in terms of actual business and that sort of thing. And so over time, I worked in a variety of positions on the ski snow school side of things. Eventually kind of moved into the sales and marketing area for a while with Blackcomb. And then after the company's merged, it was from Black merged into one company. (04:20): I got involved in this position, which is kind of unique in, and I think kind of a good thing, but kind of unique in the ski industry, at least as their business development manager and eventually the VP of business development there. So that role, it was interesting in the sense that I had some pretty big operating responsibilities, but also it was a position that was designed to help develop the kind of experiential side of what the company was able to do and what the company was able to offer. So operating side was really, snow School was the biggest part of it. Got involved in all of our major events, which is the connect into Crank Works. And then as Summer was developing, I was really involved in that in developing the kind of experiences that we could diversify into and build into in terms of the things that we could actually do on the mountain. And so the mountain bike park was, mountain Bike Park was a big part of that. And yeah, that's kind of the short version.\n\nCole Heilborn (05:32): So when did the mountain bike park first open?", "token_estimate": 479, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "03:18", "end_timestamp": "05:32", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "4e157245-2f37-42c5-bc8d-6604f4fb6870", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 3, "content": "Rob McSkimming (05:36): Yeah, the story there was as mountain biking was developing kind of in the early nineties, there was a little bit of, at the beginnings of, I call it 1.0 lift access, mountain biking 1.0. So there was a little bit of lift access, mountain biking actually on both mountains was and black home at that time. They were competitive. They hadn't merged at that point, but it was pretty limited. Largely ride your hard tail bike up and spandex and kind of ripped down some fire roads, was kind of how it was. Early on, Whistler began offering some guided tours, and that was actually a third party company called Back Roads. And the owner of that company, Eric White, was kind of responsible for the beginning of building some of the first kind of purpose built lift access actual mountain biking trails on Whistler Mountain. And so he was involved in that for a few years in the mid 1990s. And then in 1998, the Fitzsimons chair was built on Whistler Mountain and that basically that construction took place in the area where all the lift access mountain biking was taking place at the time. So essentially that put the park on hold for that year. And then in 1999, we took over the operation of the park sensing that there was a bigger opportunity for the company there. And so we began operating as a whistle mountain bike park as we know it today in 1999.\n\nCole Heilborn (07:18): Okay, gotcha. So tell me a little bit about the origins or the idea for the beginning of Crankworx, because it was born out of Whistler, correct?", "token_estimate": 387, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "05:36", "end_timestamp": "07:18", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "d1aaaf98-98b1-4916-a232-a2af96c9ce16", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 4, "content": "Rob McSkimming (07:27): Yeah, yeah, absolutely. I mean, from when we opened it to when the first year of Crank Works, which was 2004, so in five years it turned into something completely different than where it started in 1999. We were just kind of in that nexus of the evolution of Free Ride mountain biking, the change in actual mountain bike construction and bigger bikes, heavier bikes, bikes that were more suited to the kind of rugged downhill mountain bike style or mountain bike terrain that we had in the park. And so we were involved with trying to figure out how to develop the right kind of experiences in this rapidly, rapidly changing world. And I think we were just lucky to be in the right place at the right time. You had this huge scene that was building, these bikes are getting bigger. The Lift access was a solution for getting those bikes up so people could do what they wanted to do. (08:43): And then a big part of that was we were ski people that needed to try and figure out the business of mountain biking or the recreation or the sport of mountain biking. And so we definitely, again, we're fortunate to be able to connect with a lot of people who were much more involved in it than what we were, whether it's athletes, media, different suppliers that helped us along the way. And so part of that was actually developing the writing experiences, but then the other part of that is to develop the events and programs and other activities and get people really engaged in the experiences that we're building. And so Crank Works kind of evolved out of, in 2004, evolved out of having a number of different mountain biking events over, geez, I don't know, probably 10 years in Whistler starting from Cactus Cup and up through a bunch of other events until we tried to pull them together or tried to pull a bunch of these things together into what was an event designed to bring together all the different riding styles and attributes that the park had at the time. So that was how it kicked off in 2004. Okay.\n\nCole Heilborn (10:04): So gotcha. So it was really just trying to organize everything that had been happening on its own.", "token_estimate": 539, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "07:27", "end_timestamp": "10:04", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "3c872605-fe79-4011-81e0-9be5323babfd", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 5, "content": "Rob McSkimming (10:10): Yeah. Yeah. I think happening on its own, but also I think there's so many things that have never happened before and trying to, the thing was evolving so quickly, so events and experiences needed to evolve at the same pace. And so you look at some of the events that were happening were either pretty new in the world of mountain biking or we were working on developing our own approach to them at the same time.\n\nCole Heilborn (10:40): So maybe walk me through a little bit of the evolution of the event since oh four to I guess what it's become now.", "token_estimate": 144, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "10:10", "end_timestamp": "10:40", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "051f0f44-8f20-44fb-8b6a-ca55dc49282d", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 6, "content": "Rob McSkimming (10:50): Right, yeah. Like I said, just a rapidly changing journey that if you look back on 2004 or 2003 when we were thinking about it and to see what it's become today, you never would've really been able to see exactly what it became. But I'll see if I can remember some of the key moments. It really probably predated a little bit Crank Works where we had the Joy Ride Biker Cross was probably the first sort of big free ride oriented event in Whistler. And then as part of that, we did this little dirt jump competition, which was really the thing that led to the development of slopestyle. And so it was pretty cash, but we just saw with this dirt jump thing, just the number of people that came and how excited they got, there's something there. And again, working with a variety of different athletes that happened to be in the area, again, people that are really on the cutting edge of what's going on. (12:06): We started to work on this slopestyle concept, so that's probably, you look at where that is today, you go, wow, that's really come a long way. And you look at the courses, you look at what the athletes are doing, and it blows me away to this day you think, okay, it can't get any more amazing than the last event, but then you see the next event and everything stepped up yet another level. So that was pretty amazing. Other things that we did, we aired downhill. So obviously ALINE was a big part of the Whistle Mountain bike park, and it's something that we wanted to be able to bring to life in an event. We came up with this concept of running a timed event on a jump course, which hadn't really been done at that time. And now you look, there's a tour, right? There's an air downhill tour. (13:09): So that's pretty cool. One that I think was pretty interesting development was we sort of brought back dual slum, I forget what year it was. So we brought back dual slo, but I think we probably took the course to a little different level building in little bigger features, things that were a little larger in terms of their size. And we had, it's one of these things where a mistake actually led to something really cool. So we had Major, when we started the event, it was on a small budget, so we were working on the timing of dual salon, which can get kind of complicated given bracket stuff. And so the timing totally messed up, completely blew up. And so you had all these, and by that time we had a lot of the top pros in the world. So you had Kyle Strait, Brian LOEs, and others there, not really happy with what was going on at the time. (14:22): And so we were scrambling. And so as we were trying to figure this out, who goes against who? And it took a while, like half an hour, an hour of the, so back up just a little bit. One of the really cool things about Crank Works is it brings together all these sort of gravity oriented disciplines. And so you would have, in the dual Islam as an example, you would have downhill racers, slalom specialists, and you'd have the free ride guys. So whether it's at the time Cal Strait or others. So then as they're waiting for this thing to go, the guys are practicing the next thing. They're starting to do tricks on the jumps within the course. And so that we went, wow, that's actually kind of cool. So from that, the concept of dual speed style grew out of that mistake. Yeah, that's another beauty. (15:25): I think again, yeah, again, so much of such a fine line there. You try to stay really connected to the audience, really connecting, especially with some of the core influencers and that sort of thing, and try as best you can to make things happen. Sometimes they can be okay, I mean, it's a really cool idea, but you know what? It's just too, what would you call 'em, wild and crazy for a responsible company to get involved in. So finding those balances has always been something that we worked pretty hard on. And so the whip off was basically, I mean, it was a total underground event. It wasn't not part of the schedule. It wasn't officially sanctioned, and basically it would kind of filter out through the grapevine and they say, okay, show up on crab. Apple hits between blah and blah. And they had this completely separate from the organization of the event or the mountain for that matter, their own kind of casual competition. (16:40): So it just started to become to the point where, okay, you can't do this in secret anymore because there's hundreds of people watching it and there's hundreds of people doing it. And so yeah, there was a point of inflection there, so what do we do? It isn't something that we sanctioned and should we stop it or should we figure it out? So it was good we ended up working with the people that were involved and figuring out a way to do it that was stayed true to its roots, but yet could be done in a way that was responsible from our standpoint. And yeah, again, now you've got this world tour of whip offs as a result of that", "token_estimate": 1245, "speakers": ["Rob McSkimming"], "start_timestamp": "10:50", "end_timestamp": "10:50", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "67c2353a-ef05-4685-819c-bdcb79a329dd", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 7, "content": "Cole Heilborn (17:30): Started in oh four, it's evolved over the years. Every year it sounds like it is just gotten bigger. At what point did it become a world tour? How did that get started because there's other legs to the event or there's other destinations for the event?\n\nRob McSkimming (17:47): Yeah, so the history there was in the earlier Crank Works Whistle Blackcomb was owned by a company called Intrawest who owned a variety of resorts in North America. And one of the resorts that they owned was Winter Park in Colorado, and Winter Park was a great mountain biking destiny or is a great mountain biking destination with the mountain bike park that they were working hard on growing and establishing. So we were part of the same company. We were involved in working with them, giving them some of our thoughts and ideas as far as that's concerned. And then it just made sense, okay, we're the same company. We're trying to do the same things with the interest in Crank Works, both from an audience standpoint, a sponsorship standpoint, there's definitely an opportunity to move into the US and certainly some of our sponsors like sram for example, with David, the opportunity to move into the US just would make some sense. So that was sort of the first second Crank works, I guess. (19:09): And that lasted for a little while, and then some things changed and they decided they wanted to kind of go in their own direction, which was great. It totally made sense. But in the meantime, so that sort of thought of having more than One Crank Works was born. And then I would say the other thing that was happening there, as Crank Works became a bigger and bigger player on the world stage, we had more and more people coming to Whistler and going, this is a cool thing, how can we learn from it? But then more than going, Hey, could we do one of these at our place? So I guess part of it was we thought it would be an interesting way to continue to promote Whistler and the Whistler Mountain Bike Park on the world stage. The other side of it was we had people coming to us and saying, Hey, what do you think about this? So we gathered our team and tried to figure out how we could do this, and that was the beginning of the World tour,", "token_estimate": 562, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "17:30", "end_timestamp": "17:47", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "5892fd28-087a-4106-bcce-79ce7793808c", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 8, "content": "Cole Heilborn (20:10): And Crankworx is coming back in 2022. And where is it stopping?\n\nRob McSkimming (20:17): Well, currently, so Crankworx Whistler has been postponed for 2021, but they do have, there are other two events in Innsbrook, Austria, which is coming up soon. And then their event in Rota New Zealand, which they've had there for what a number of years now is happening this year as well. And then in 2022, you'll have the same three destinations as a minimum on the world tour.\n\nCole Heilborn (20:45): So what I've found really interesting, and I think one of the things we chatted a little bit about is, well, one, aside from the fact that the event just kind of happened kind of naturally, but as you said, it kind of happened by accident. You kind of got lucky with all the right pieces falling into place at the right time. I feel like this, and there's other events that I think speak to this as well. I am imagining Tour de France or Sea Otter where it's this blend of racing events, experiences, brands, products, merchandise, spectators, participants. It's kind of this perfect storm of worlds coming together. I guess from a marketer's perspective, it seems like an awesome thing to be a part of. It seems like sometimes these types of events, I don't know, are they taken fully advantage of? Are they sometimes not considered from a brand's perspective, I guess how do brands view these types of events and how do they take advantage of them or how have they used them in the past?", "token_estimate": 377, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "20:10", "end_timestamp": "20:45", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "2102f713-f275-44ca-9191-b715faf7d329", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 9, "content": "Rob McSkimming (21:48): I do think it is funny. As we were starting these things, part of our vision for Crankworx was actually modeled after the World Ski and Snowboard festival that happens in Whistler every April and had been pretty well established at that time. So as you said, it was kind of, this was rare at the time, this mixture of sport arts called and call it entertainment, blending all those together into this one big happening. And so that was definitely part of our vision at the time. And if you look at Crankworx over its evolution as an example, there used to be a lot more music involved in Crankworx at the beginning. So there's a big stage, and music performances were a big part of it. It's kind of evolved over time, but the bringing together of all those elements was definitely a key part of it. And then I do think having these events in this resort environment really helps to bring it all together, as you mentioned. (23:00): And so if you're a brand and you're involved in an event like this, I mean, it gives you, at least that was our design. It gives you a few opportunities. So one, it attracts a lot of people. And so you've got this on, whether it's Sea Otter or whether it's Crank Works, you have a lot of your target market in one place at one time that you can display, demo, engage with people that are there. And for us at the event organizers, it was great because it added to the entertainment, it added to the value that people coming were able to get from the event. So it was one of those kind of win-win situations. And then the other thing that we worked really hard on, I think we're pioneered in terms of the mountain biking event landscape at the time was we were really hard on being able to take the action and broadcast that, or webcast that (24:13): We were pretty pioneering a little bit on the webcast side of things because broadcast was just hard. It's hard to get into, it's expensive. Whereas as web-based media was starting to happen, it gave us this opportunity to do it, well do it super professionally, but do it in a budget that was affordable. So for brands, we felt we could provide that opportunity not only to have the in-person audience, but also to have the worldwide audience. And so, I mean, I forget the latest numbers, but it's millions, millions of people turn in now versus in a resort, if you get a couple hundred thousand people over the duration event, that's the best you can possibly do. So I think there's both aspects to it.", "token_estimate": 628, "speakers": ["Rob McSkimming"], "start_timestamp": "21:48", "end_timestamp": "21:48", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "8e895272-2794-413a-a160-b8483ea4da98", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 10, "content": "Cole Heilborn (25:04): How important is an event like Crank Works for your average bike brand as part of their annual plan?\n\nRob McSkimming (25:17): I think it kind of depends a little bit on the brand, but when you look at RA, for example, and they would be one of the bigger investors in Crankworx, if you like, both from the standpoint of a sponsor, but also from the standpoint of their actual activation. And so for Aram, yeah, it's big. If you look at their overall marketing plan, their overall marketing budget, it's a pretty significant portion of that for sure. I think on the mountain bike side, it kind of like Road guys would look at Tour de France, right?\n\nCole Heilborn (25:58): I think is really interesting is you have all these people of the right demographic in a location all participating, but at some point it goes beyond the companies that are there tabling and have their booth set up. It's part of a much bigger, it's a culture thing. How important is it for brands to be involved in these types of culture defining events?\n\nRob McSkimming (26:27): Yeah, I mean I'm probably a little biased, but I'd say, yeah, I think it's really important. I think it's a really, really interesting question, really. And so it's like, okay, if you look at Pink Bike when Crankworx is on, it's a week, two weeks before, during week, two weeks after. I mean, it's dominating the news in the world of mountain biking at that time. And so I think for brands to be part of that culture being where it's happening, being associated with a place where it's evolving, the place where it's innovating, the place where the influencers are there. And so I think being associated with that, if you can catch that critical mass, if you're thinking about it from the event side, you can catch that critical Mass Boy, things really start to explode from there. But it's not easy to do because the calendar's so full. And so even as you expand Crank Works events and you have ECIF, sea Otter, you, there's a number of different places people can invest their time and money. So trying to figure that out is not super simple.", "token_estimate": 530, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "25:04", "end_timestamp": "26:27", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "d8dd96ef-c9e6-4dbd-9c22-cf657042c77a", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 11, "content": "Cole Heilborn (27:41): Sure. But elaborate on that. Why is that so important to be right at that core of the evolution of the sport or where it's happening?\n\nRob McSkimming (27:53): Well, yeah, I do think there's a rub off effect to your brand. And so I think most brands, especially in mountain biking where innovation and being seen as being leaders if you like, in whatever particular segment that they're in is really important. And so I think how can you communicate that? Can you communicate that in a magazine ad? Not these days, but it is tough. You do your own videos and things like that. You can work with athletes, but the thing with Crank Works is you can bring Crank Something like Crank Works, you can bring all that together in one place. And I think Crank Works just, I think Crank Works just adds to the energy of all that. It gives you that sort of context, that sort of backdrop. And I think because people are paying attention, it increases the likelihood that they're going to tune into your message.\n\nCole Heilborn (29:10): So kind of coming back to that culture idea, you might have Aram tent right next to a Shimano tent and outside of that event, they're competitors. But what about, or is there anything special I guess, about the world of mountain biking that because when you get to the event, everyone's having fun, there is no sense of competition or, oh, we don't hang out with those guys trying to beat them this year. I guess what about the event or what about the culture feels that way? I guess why is that brought out?", "token_estimate": 389, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "27:41", "end_timestamp": "29:10", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "739849f1-7af3-4ea6-9c26-a751a31790db", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 12, "content": "Rob McSkimming (29:43): Yeah, that's a good point. Again, I think it's partly just that environment that you're in. You're in this kind of resort environment. One of the things I think it helps that is everybody's really active. And so I find with the event, it's not just you have the pros going out there and performing, and then you have other people watching and then you go and do whatever you're going to do. This is one where amateurs compete with pros on the competition level. This is one where if you're not watching an event, you're out riding your bike yourself. If you're not manning your booth, you're out riding the park or you're out riding the trails around. And so I just think because it's more than just the business of what you're doing, it's part of the overall, as you said, it's part of the overall culture of mountain biking. And I think that's whether you're competitors or whether you are not, I mean, I think that is a shared attitude. And so I think that's part of how people who would otherwise be pretty feisty towards one another actually can be, especially honestly, especially see it the later the evening goes and the more the party goes on. Yeah, it's a full congenial mix of people having a great time no matter who they work for.\n\nCole Heilborn (31:19): Well, probably because of the shared lifestyle, right?\n\nRob McSkimming (31:22): A hundred percent. Yeah. And again, I think that the thing with the event there is you're actually doing that lifestyle at the event as opposed to promoting that lifestyle or promoting your product, you're actually participating in the lifestyle.\n\nCole Heilborn (31:35): Oh, interesting. Yeah, I never considered it from that perspective.\n\nRob McSkimming (31:39): I think of all the people that are there, the supplier group, they're all riding, even have some people that are, maybe they're businesses in outside of a mountain bike area or an urban center or even Asia or whatever, and they may not be huge mountain bikers, but when they're there, they will definitely ride a bike. They'll definitely go try out the park. And so I think it does because of those options are all there, I think it helps to bring people together.", "token_estimate": 550, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "29:43", "end_timestamp": "31:39", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "81a986a1-85d2-4f18-b3ef-7019299e0b7e", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 13, "content": "Cole Heilborn (32:10): How important do you feel like experimental marketing is in today's world? And I know it's kind of limited for the obvious reasons, but will it become more important as more events start happening?\n\nRob McSkimming (32:24): Yeah, yeah, I think so. I mean, think you definitely hear a lot about how our global economy is evolving and moving more and more towards a sort of experienced economy or experiential economy. And so I think as more businesses become predominantly involved in the creation, development and promotion of experiences, you'll get more and more people figuring out how they package and promote those things from a marketing standpoint. So yeah, think it's really important. I would add to that, I think one thing that will grow or could grow in terms of the world of experienced providers is the actual, I would almost call it product development. So what are people doing on the experience side actually evolve, develop, and improve their experiences over time. And I think in the hard good side of things, there's a really clear path to that. On the experience side, I think it's still evolving and developing.\n\nCole Heilborn (33:35): Oh, interesting. I want to go down that path a little bit, but back up really quick. You mentioned that experiential events, that's the way that the economy is moving. How did you phrase that?\n\nRob McSkimming (33:49): Sorry, I just meant probably a little broader than events, but just that when you look at the percentage of, I can't remember the stats, but the percentage of the economy, call it GDP or whatever, that will be taken up by experience, call them products, is expanding. So your normal goods and services are becoming a smaller piece of that pie as the experience side continues to grow. So\n\nCole Heilborn (34:21): It kind of strikes me as being ironic because experiences are growing, but so is the digital world, which seamen odds at each other, but they also can compliment each other.", "token_estimate": 496, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "32:10", "end_timestamp": "34:21", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "1f9083fc-9487-4b1b-81cd-c5f8f8c3f096", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 14, "content": "Rob McSkimming (34:31): I do think that's an interesting point. And on the one hand, you're seeing an increase in the amount of screen time people have around the world and across every demographic you can imagine. But on the other hand, you're seeing it and you saw it pre pandemic, but you're seeing it huge during the pandemic. You're seeing this massive, massive, massive increase in people seeking outdoor home experiences, both from the recreational side and from the softer, just getting outdoors really. And so both things are happening, and I don't think they're mutually exclusive at all. I think that's a thing that we thought was the case. I think we thought that screen time would take away from outside time, but in fact, I think we're seeing people're taking their screens with them and they're going out and actually there's more, there's a greater number and a bigger diversity of people seeking those outdoor experiences. And so again, I think there's massive opportunity as a result of that.\n\nCole Heilborn (35:42): Okay. So take me back to your comment earlier about evolving events and comparing that to product design.", "token_estimate": 285, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "34:31", "end_timestamp": "35:42", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "ec722773-b099-4b35-aca0-f50ce07156eb", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 15, "content": "Rob McSkimming (35:50): Yeah, I think it is, whether it's events or it's the actual experiences. So I would say in the bike park, how do you, as time goes on, as rider preferences change, as bike technology changes, how do you adjust the experiences that people are having on the mountain? What's the process to get there? And then the same with events. I mean, those things absolutely connect. So as those things are changing, what's the process for you to evolve your events to meet those changing needs that are occurring as a result? And so one thing that I always found that worked well with us is making sure that you're engaging with the right people and again, just the way you would on the product side. So what kind of information are you getting? What kind of research are you doing? For us, I think a lot of it was, boy, it's changing so fast. We can't be on top of everything, but we can broaden our base, we can work with bigger teams, we can work with a more diverse group of people to try to get an understanding of where it's going and then figure it out from there and drive that process from there.\n\nCole Heilborn (37:15): So that sounds kind of like a bit of a chicken and egg scenario. Do we evolve the event before the sport is ready or do we let the sport evolve the event? Yeah. How do you do that? You guys think about that. Were there, I mean, I guess maybe some of those examples you gave earlier, the whip off was kind of an example of how do we manage the evolution of the sport?\n\nRob McSkimming (37:39): You know what, I am not entirely sure. I do know that when it comes to mountain biking, I think experiences need to play a greater role in actually driving things forward and not be the passenger. And when you do, so when you create an A line or when you create a crank works, are you creating where the culture's going or responding to it? And I always feel like it felt to me like it was a bit of a blend of everything. One thing wasn't necessarily ahead of the other, you were just all trying to keep up with one another.\n\nCole Heilborn (38:17): Sure.\n\nRob McSkimming (38:18): Curious to know how you think about it.", "token_estimate": 539, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "35:50", "end_timestamp": "38:18", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "f3dd7ad1-727e-415b-99cd-f118669f1452", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 16, "content": "Cole Heilborn (38:21): Oh man. Yeah, I don't guess I don't have an answer other than something that I've thought about a lot is thinking about the technology in a mountain bike and the trails that are being built. And I don't know if it can be so simple as I'll say it, but is it the trail that's defining the bike or is the bike change and the technology and the bike creating the momentum for the types of trails that are being built? And so that's something I've considered a lot is how does that relationship look like? What does that look like on a very granular level, on a very high level view? I don't have an answer, but it's something I've thought about for a while.\n\nRob McSkimming (39:08): Bringing it back to the event side of things. I mean, I do think there's something there. It becomes this incubator where all that stuff's in one place at one time. All those people are in one place at one time. And then what happens in the future that had an influence over it is hard to know. But you got to think that because that happened, things will evolve in a certain way just because everybody was in the same place at the same time doing similar stuff.\n\nCole Heilborn (39:38): So yeah, considering that, I guess from your role in the management and leadership perspective of the event at some point where you just like, you know what guys, we're, we're going to do the best job we can, but we're just going to be along for the ride and see what happens. It is about the people, it's about the culture, it's about the community, and ultimately they're going to help us create the best event if we structure it that way.", "token_estimate": 408, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "38:21", "end_timestamp": "39:38", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "7dad8023-5fab-407e-8eb2-bb192d680477", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 17, "content": "Rob McSkimming (40:01): Yeah, a hundred percent. Always our attitude and continues to be the attitude at the group is running it now is staying really close to that. And then as I said earlier, then the job is finding a way to make it work. I mean, there's tons and tons of ideas out there once you start coming your way through them. But the chore if you're the operator is okay, how do you make it work? I think that was always our attitude was, okay, okay, you guys think that's good? We like that. Let's try and figure it all out. We would have every year the crank works that happen, we bring together all of the main sponsors and that sort of thing and have, I would call it a bit of a presentation, but really a bit of a symposium to go, okay, here's going on here, here's what we're doing, here's what we're thinking about for the future. What are you guys seeing and how can we work together to make things happen?\n\nCole Heilborn (41:09): And those types of examples, how much of the success of an idea is based upon timing and the placement.\n\nRob McSkimming (41:16): Yeah. Yeah. I think as I say, timing's a lot, right? Timing's everything. Yeah, I think that's a huge part of it. And so you can be too soon or you can be too late. So I'll give you an example with Crank Works as it's a good way of bringing to life some of the things we were talking about earlier. So as you think of the bike technology, it goes from cross country to these bigger bikes, and then slowly those bigger bikes get lighter and smaller, and then now you get bikes that are capable of pedaling but also very capable downhill. So you get the introduction of Enduro style events that we got heavily involved in, but I would say our ability to make, we probably tried five different things before the right concept, bringing together the right bike technology and what riders really want to do from an event perspective actually jelled into place. So I think you've got to work with those groups and then try some stuff and then kind of iterate as you go through and go, okay, that didn't work. Now what do we do? Right.\n\nCole Heilborn (42:40): Interesting. What were some of those events? What didn't work about?", "token_estimate": 550, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "40:01", "end_timestamp": "42:40", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "70b47955-d93e-4e41-8939-95f0fd888b99", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 18, "content": "Rob McSkimming (42:44): Well, I think part of it was Enduro was happening huge in Europe, in North America. It just took a little while for people to get outside of their, I'm an XE guy or I'm a downhill guy, or I'm a free ride guy or girl. And so you remember you had Super D and Enduros could be different lengths of time and different trails and certain enduros might require a certain bike, others a different bike. And so I took a while before the concept that we now have these sort of multi-stage events with liaison stages in between that aren't timed that really kind of jelled that. So part of that was part of how we got involved with that is we became Partners, ownership partners in the endur World series when it first began. So again, working with other people to try to make this happen. So in this case, people in Europe were way ahead of us, so we ended up taking concepts that originated in Europe.\n\nCole Heilborn (43:56): I'm curious, so through all of this, and I know you were part of a team and it wasn't just you, but I guess how does it feel knowing that you played somewhat of a role in helping develop an event that those in the mountain bike industry look at and they're like, yeah, this is one of the events of the year that I'm going to.\n\nRob McSkimming (44:19): You know what, it was fun. I miss it. It was really fun. I'm still on their advisory board, but that means I get to talk to them once every few weeks kind of thing. So yeah, no, it was really fun to be a part of a thing. It was so dynamic and involve so many people. And yeah, there's just an energy to it when you're involved in it and you're working with a really dynamic group and you're able to accomplish some things and you're able to see. Yeah, I used to, on the slopestyle day, I used to just get out onto the event area and just walk the whole area and just really kind of soak in what was going on there. It pretty exciting to be kind part of that energy. Yeah,\n\nCole Heilborn (45:25): I can only imagine. But Barb, it's just making, wanting to go back as you're talking, I'm like, shoot, I can't wait until it opens up and we can go again.", "token_estimate": 536, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "42:44", "end_timestamp": "45:25", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "fcbc98cf-7498-447c-9e79-a3797393aab1", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 19, "content": "Rob McSkimming (45:35): Yeah, I feel it's really too bad. I think it's so close to being able to happen in the normal sort of mid August time slot and it's just, I mean, CC Otter now has announced that they're going in October and yeah, it's close, but I think that said 2022 will be, I think that sort of pent up energy will just be electric. And so if people are out there thinking about what to do in August of 2022, I start booking your trip pretty soon.\n\nCole Heilborn (46:19): What made Crank Works successful? We've talked about a few different things that were definitely important, but I guess why did it all work?\n\nRob McSkimming (46:27): Well? Yeah, I think there's a number of aspects. I think some, just as we've been talking, being in the right place at the right time, so a bit of good fortune I guess. And then, which I think was really important. I'm not sure if you try to start that event at the time that we did in Eastern Canada that would've caught fire just given what was going on in the areas. But then, yeah, I think again, I think the key to its success over and above that is being able to bring the right people together and then be really dedicated to working hard to be able to shape the experiences that are going to be interesting to the audiences that you're targeting. So whether that's the onsite audience, the athlete audience, it was really important to us that the industry felt really good about it. So that was another important segment. And then really on the media side also was really critical. So if you can get all of those things working well and being enthusiastic about what you're doing and providing you with good information and you're smart about how you take that information and figure out how to make it happen, it can be really big.", "token_estimate": 448, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "45:35", "end_timestamp": "46:27", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "c5f69b94-7962-4462-9559-135999801c35", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 20, "content": "Cole Heilborn (48:08): And I just consider as you're describing that, I'm thinking like, man, I wonder what sort of impact Crankworx has had on just people who just show up. How many people decided, Hey, I'm going to start a mountain bike company. I'm going to start something related in that industry. I'm going to start a company because I went to this event, or how many people went to the event and were like, shoot, I'm going to start. I'm going to get on a mountain bike I've never ridden before, but this looks like really a ton of fun. I can only imagine what sort of impact that's had on people over the last, well, 15, 16 years.\n\nRob McSkimming (48:45): Yeah, that's interesting. Yeah. Mean how do you know? But I do think it has enough critical mass that it has had some influence, that's for sure. Whether it's on the more experienced riders or people that are kind of new to the sport. I mean on that end, I mean it's always been a goal and kind of a hard one really, is to be able to use the popularity of the event to broaden its appeal to make it more mainstream. At the same time, the things that people are doing at Crankworx are so crazy that it could actually take it in the other direction. You know what I mean? People could see it, watch slopestyle and go, man, I ain't riding a mountain bike. I'm not doing that. Yeah. And I think now with the pandemic and the number of people that are riding and getting outdoors, that group has now broadened. It's getting close to mainstream. And so now you've got this bigger audience and are the experience that you're providing, what's the messaging that you're providing and how do you adapt to that going forward?\n\nCole Heilborn (50:03): I guess what would you say if you were in a room full of marketers or you're just talking to our audience, which are predominantly folks in the marketing world, from the things that you've observed and helping develop Crank Works, I guess, what should folks be paying attention to? What do you think is really important for the future of the industry in relations to marketing looking forwards?", "token_estimate": 525, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "48:08", "end_timestamp": "50:03", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "2b9db46d-436c-4807-bab7-fa28d8122957", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 21, "content": "Rob McSkimming (50:30): Yeah, I do think there's just this massive opportunity given the increase in the market, again, based on, I think based on, as we said earlier, I mean really based on our trend that I think was already there. I just think it's been really amplified as a result of the pandemic. So I mean, you look at bike sales, you look at anything to do with biking sales just through the roof. And so you've definitely got this quantum uptick in the market. And so now what happens? Do those people that tried it because they had nothing because all the other recreational sports were kind of on hold, do they just park their bike in the garage and not go? So you have this opportunity to get out there and really engage with these people. And I think in some cases it might be kind of tricky because in some cases your business, it is firing. (51:32): I mean, it's through the roof. And so you could certainly make an argument that, well, we don't need to do more marketing selling everything out, but yet there is this industry opportunity there to be able to go, okay, now how do we really make this thing happen? So I think it's having a better understanding of those people that are being introduced into the sport. And then what kind of messaging should you establish for those people? How do you get them involved? And I think a really interesting way there is getting them involved on the programming side of things. So how can you get more people to participate in clinics and programs and eventually into events and things like that. And so again, all working together to do that I think will help to have those people that are trying it stay involved with it. And so I think that's a huge of each part of it.\n\nCole Heilborn (52:34): Interesting. So unfortunately we are coming close to the end of our time today, but so one of my last questions I guess is yeah, how is Crank Works looking at this new audience? How are you, or not you specifically, but how is Crankworx trying to include and welcome them? Is that something that's being considered?", "token_estimate": 518, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "50:30", "end_timestamp": "52:34", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "30c5bca0-4a13-4344-b348-64cef133054e", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 22, "content": "Rob McSkimming (52:58): Yeah, I think Crank works with the team that's there now. The person that is the general manager and owner, Darren Kard has been super progressive with being very inclusive and have been doing it frankly for a long time. So I mean, if you look at prize money, prize money is the same women and men, you look at podiums, men and women are on the podiums, so doing a lot to try to grow that female side of the market. You look at what they're doing with kids, I think it's massive. So every single stop, there's Kids Works events, and so you've got kids participating at super young ages like three, four or five years old, and there's a real focus on that. So you look at so many examples of people that started in Crank works in these sort of junior events that are now world caliber athletes. And so I think for Crank Works, it is more of that. And then again, working on one of the things they're really good at, which is being able to take their message and get it out into the world through their webcast platforms that they've got out there. So I think they've got a good foundation in place to take advantage of where the market's headed right now.\n\nCole Heilborn (54:24): Interesting. Well, awesome, Rob. Yeah, again, I'm super excited to come up and visit the next event. I appreciate you taking the time to chat today. It's been great to learn more about how the event got started. I think I know when I showed up I was like, this is just cool. I have no idea how it began, but I appreciate you shed a little bit of light on that. And yeah, I just think this idea of experiences, culture, how that all connects to marketing is a really interesting conversation and what a great case study to kind of look at and dissect a little bit. So yeah, thank you for the time.\n\nRob McSkimming (54:59): Yeah, thank you. It's been fun. It's great walking down memory lane again.\n\nCole Heilborn (55:04): Well, if folks want to get connected with you, if they just want to go for a ride or talk shop, is there a good way people can find you?\n\nRob McSkimming (55:12): Yeah, what do I provide coordinates or just look for me at the bike park or,", "token_estimate": 541, "speakers": ["Rob McSkimming", "Cole Heilborn"], "start_timestamp": "52:58", "end_timestamp": "55:12", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "e4456228-db3c-46c9-9693-c9f034f2d52c", "episode_id": "6efd5261-3634-4b22-b677-8e3602f454a1", "cms_item_id": "68225dfc7bb476527f8c486c", "chunk_index": 23, "content": "Cole Heilborn (55:20): Yeah, Latin Long Works, if that's the best way to find you.\n\nRob McSkimming (55:23): Yeah, yeah. Do you drop my email? So it's just R mc Ski, so RM cs K i@me.com.\n\nCole Heilborn (55:29): Awesome. Sounds good, Rob. Well thank you again and I hope you have a great rest of your day.\n\nRob McSkimming (55:34): Okay, cool. Thanks.\n\nCole Heilborn (55:36): Alright, take care.\n\nRob McSkimming (55:37): Alright.\n\nCole Heilborn (55:39): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 166, "speakers": ["Cole Heilborn", "Rob McSkimming"], "start_timestamp": "55:20", "end_timestamp": "55:39", "podcast_index": 69, "episode_name": "EP 69: Rob McSkimming | Origins of Crankworx | Whistler Blackcomb", "slug": "ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "web_url": "https://www.portsidepro.com/podcast-feed/ep-69-rob-mcskimming-origins-of-crankworx-whistler-blackcomb", "guest_name": "Rob McSkimming", "guest_title": "(formerly) VP of Marketing, Whistler Blackcomb", "categories": [], "short_description": "Starting in 2004, Crankworx has quickly gone on to fuel the evolution of mountain bike culture, attracting fans and athletes from around the world.", "podcast_length": "44:91"}, {"id": "c28f753a-1a53-4cab-ab42-df9e75f48954", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 0, "content": "Bonie Shupe (00:05): We started on this new on ivex 2.0 together and really relaunched the brand. And so one of the core things that I have always been trying to look at is what did 1.0 do really well and how can we take that forward in 2.0 and build a brand that is going to be a heritage brand that will last and grow and be also innovative with the Times?\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing podcast. My name is Cole Hile, born and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Port Sided Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Hilborn, and today I'm sitting down with Bonnies Shup and Jordan Totter off. They're here representing iex Jordan and Bonnie, how are you guys? Doing\n\nBonie Shupe (01:17): Great.\n\nCole Heilborn (01:18): Yeah, well, yourself doing fantastic. Yeah, thanks for joining me today. Where are you guys calling in from?\n\nBonie Shupe (01:24): I'm up in Netherland, Colorado, just above Boulder,\n\nJordan Todoroff (01:29): And I'm in the San Francisco Bay area, sunny San Francisco Bay area.\n\nCole Heilborn (01:33): Awesome. Well, thank you for joining us. I'd love to learn more I guess, about each of your guys' roles within the company, and then also if you could share what outdoor hobbies or activities you're currently enjoying doing. I had love to learn more about you guys.\n\nBonie Shupe (01:49): So I am the GM and the director of product for ibet, and I was part of the relaunch team and have been with the brand since we started. And my favorite hobby currently is trail running to fish. So I bring my rod with me. My partner just bought me a 10 Carra rod and I absolutely love it.", "token_estimate": 527, "speakers": ["Bonie Shupe", "Cole Heilborn", "Jordan Todoroff"], "start_timestamp": "00:05", "end_timestamp": "01:49", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "266e2e56-5ae7-4929-a18a-e97add22bb81", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 1, "content": "Jordan Todoroff (02:13): And then I'm the head of sales for Ibex. So as Bonnie really was brought in to relaunch the brand with her expertise and background in the sphere in due time, she brought me in and I work in a lot of areas, but helping to relaunch the sales for Ibex and get it into people's hands. And I'm a pretty passionate hiker, backpacker, climber, mountaineer. I also noticed that Bonnie elected to Eshoo the fact that she did just take first place in her category in the big horn.\n\nCole Heilborn (02:43): Whoa.\n\nJordan Todoroff (02:44): It's pretty wild for a\n\nCole Heilborn (02:45): 52 mile race. Oh my goodness. Were you doing that with a fishing rod in hand?\n\nBonie Shupe (02:51): No, actually I try not to do racists anymore, but sometimes, well, a lot of times my friends, whenever they have a big endurance thing that they want to do, they always ask me to come along. So I went and did the Big Horn and I actually absolutely loved that course and would do it again in a heartbeat. It was so much fun.\n\nCole Heilborn (03:15): Wow. Well that sounds pretty incredible. Congratulations. So I guess when I introduced iex, I wasn't sure if I should introduce it as IEX or IEX 2.0 because that's kind of what we're diving into in our episode today. I didn't realize this until after I met you guys, but well, one, I first had to learn about the entire history of iex, but it sounds like you guys have been on a pretty incredible journey and I'd love to learn a little bit of the background of iex, the rise in the fall and now the resurrection and you guys are running with it forward. So could you give us a little bit of background on the company?", "token_estimate": 417, "speakers": ["Jordan Todoroff", "Cole Heilborn", "Bonie Shupe"], "start_timestamp": "02:13", "end_timestamp": "03:15", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "a6e26c87-c192-44eb-862d-03d234f77349", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 2, "content": "Jordan Todoroff (03:55): So IEX was an icon brand, really founded kind of the birth of the Merino movement. So synthetics were on the rise throughout the sixties, through the eighties primarily they became pretty affordable to produce and companies jumped on with that, right? Some real legendary outdoor brands took those and ran because they gave performance characteristics that people needed, right? The ability to wick moisture, dry quickly, stretch, and move with our bodies as we need to temperature regulate those kinds of things. So they became really cheap and they got the job done. But in the early nineties we started to realize that this sheep, the Marino, which is very likely the oldest breed of sheep on earth, naturally grew this fiber. That's an absolute miracle. So it wicks moisture, it dries quickly, it temperature regulates, stretches and moves through your body, all just designed by nature. So really phenomenal characteristics and obviously there's a great environmental story there to be told. (05:02): And the fact that you're not deriving it from petroleum and brands started to realize that this could be used to keep you cool in the heat and warm in the cold both. And as it dries and wicks that moisture weight, it actually prevents bacterial and microbial growth so it doesn't stink like other fabrics do. So you're able to use one piece for this huge variety of different applications. So in the early nineties we started to realize what a miracle fiber this was. And two gentlemen on the East coast based out of Vermont took this idea and really fell in love with the fact that this was when we consider the fact that polyester and nylon have been developed for 40 and 70 years, somewhere in that category. But renal fiber is the oldest breed of sheep likely on earth. You think about the amount of time that goes into that design and the consequences if the design is bad, if you're a bad scientist, you get fired. (06:04): If you're a bad sheep, you die. So nature is quite the teacher and yeah, two guys who love the outdoors and saw the potential in this ran and built this apparel brand that gained incredible traction throughout the us. And so sportsmen from all over realized that this polyester and nylon, they were developed to do the job, but not necessarily to be comfortable. And personally as someone who's fallen head over heels in love with Marino, it's just the most comfortable fabric for any application I've ever used. I'd never go back at this point. So those guys founded it as this real passion project and put their whole lives. They had family and friends involved and this really tight community out of Vermont and their customers were a part of that community as well. They contributed to those conversations and just had this absolute cult following. And so Ivex 1.0 got this incredible reputation for phenomenal quality, the most comfortable fabrics, the highest, most elite quality textiles of their kind really on earth that were available. (07:11): And it went through several iterations as the company grew and changed and flexed over time, they made phenomenal, pretty legendary cycling gear and they made garments for backcountry skiing and mountaineering, but a lot of firsts. That's what I think when I think of IEX in the Marino sphere, I think of a lot of firsts. So really pioneering things like seamless construction, windproof, highly water resistant, a hundred percent merino textiles, a lot of real textile innovation. And the company grew and changed over time. And unfortunately in the end of 2017, early 2018, IE started to wind down and came to a close. And so that's where Bonnie came into things.", "token_estimate": 921, "speakers": ["Jordan Todoroff"], "start_timestamp": "03:55", "end_timestamp": "03:55", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "62ff6dc3-13f2-445b-a525-99fa311170fe", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 3, "content": "Bonie Shupe (08:03): Yeah, Ben Flower Fund actually bought the brand and they were kind of wondering what to do with it. They loved the idea of the community and they really buy communities because that's something that really attracts them when they're looking at buying a brand. And so as IEX 2.0, they were looking at what they were going to do and who could take the reins, and we were put in contact, and I went out there and talked to them and really liked the owners. And so we started on this new on I VX 2.0 together and really relaunched the brand. And so one of the core things that I have always been trying to look at is what did 1.0 do really well and how can we take that forward in 2.0 and build a brand that is going to be a heritage brand that will last and grow and be also innovative with the times. And so that's really one of my focuses with IX 2.0. So\n\nCole Heilborn (09:12): Bonnie, how did you come to take the reins? Were you a fan prior? How did you get connected with the folks at Flower Fund?", "token_estimate": 256, "speakers": ["Bonie Shupe", "Cole Heilborn"], "start_timestamp": "08:03", "end_timestamp": "09:12", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "e8d55a49-cc74-4417-9e31-1acf289c5bf9", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 4, "content": "Bonie Shupe (09:19): Yeah, I've always been a fan of Marino Wool and Ivex in general. And I had been a consumer of their products for many years. I actually, I have been in the outdoor space for years since 2002, and I just absolutely adore Merino. And so when I got to the point where I actually wanted to make a career switch, I was a graphic designer before I went back to school and I have a degree in both apparel design and in textiles and spent a lot of time actually taking roll from Fiber to end product. So I've actually had the opportunity to do everything from she all the way through to the end product. And so it's really pretty awesome that I get to take the reins of Ivex. So when we were in touch, everything just kind of synced and they knew it was my dream job and I knew that I liked them and it worked out. (10:23): So here I am and I get to use everything that I've learned throughout the years and it's just making it happen. And I started as just their product person. And what happened is we were looking for a GM to really take the reins at this larger scale for the brand. And when we started really analyzing what to do and what the next steps were for that, the board decided that really I was kind of the heart of the brand and that they felt comfortable with me taking the reins there. So even though I don't really have that background, what I do have is a love of this brand and a mission to do what is right for the brand. And so they kind of trust me in this position.\n\nCole Heilborn (11:16): And I guess what did happen in 2017 and 2018, what led to the brand 1.0 is demise ultimately", "token_estimate": 405, "speakers": ["Bonie Shupe", "Cole Heilborn"], "start_timestamp": "09:19", "end_timestamp": "11:16", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "6d3a2883-2097-4c17-867b-ef9c1ad33839", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 5, "content": "Bonie Shupe (11:25): I bet said a lot of things that were not necessarily well planned. The one thing is way that they developed new skews, a new product, they had way too many products for the amount of sales that they had, and they had no hero product. When they did have a hero product, they often would look at that and say, oh, let's split this product and we'll make a new product off of this hero product, which they really should have done was just continue to hone that hero product and really champion it moving forward. So that was one thing. There was a series of just financial risks that didn't pay out for them in the end. And I think there was just a lot of increased competition and people who were really smart with their marketing and business decisions and IEX was really so focused on innovation and product that they weren't fully, I would say they weren't fully aware of all the competition around them.\n\nCole Heilborn (12:34): Okay, gotcha. There's an article on outside that talks about their switch from wholesale to direct to consumer, and it sounds like that switch also had something to do, maybe add on top of some of these other issues.\n\nBonie Shupe (12:48): Yeah, I would say that was one thing. One of the strategies that they thought would be really helpful for them was to pull out of wholesale and just do direct to consumer on the web. And I think that was a really drastic, they really made that a drastic turn and it probably wasn't the smartest turn, especially because they had built 1.0 was built on their community. They were built by people who really loved the brand and championed the brand. And so when they pulled out of those wholesale shops, they kind of burden them and that really caused some friction.\n\nCole Heilborn (13:37): Yeah, interesting, man. You mentioned, or Jordan, feel free to jump in. I'm curious, you talked about a hero product and the importance of a hero product, hero product. Why was that a problem not having a hero product or having too many hero products? What's the issue with that?", "token_estimate": 515, "speakers": ["Bonie Shupe", "Cole Heilborn"], "start_timestamp": "11:25", "end_timestamp": "13:37", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "519a4fe4-9e65-422f-828b-13385ca7d723", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 6, "content": "Bonie Shupe (13:57): It's just resources is really what it comes down to make a really great and beautiful product to want to be able to spend enough time on it to champion it and make it irreplaceable. And I think when you don't spend the time on that product to champion it and hone it and make it better that you can't do that for every single one of your products. So if you can really hone your energy towards the products that are your champion products, I think that's just a good business sense. Okay,\n\nCole Heilborn (14:34): Interesting. And so how long was the brand dormant before it's been revived?\n\nBonie Shupe (14:41): Just a year and a half.\n\nCole Heilborn (14:42): Okay, gotcha. And then when you guys stepped in, I guess, what type of assets or resources or product did you have at your disposal? I mean, did you just take the name essentially and start from scratch or were there legacy pieces that you could use to help get the ship moving forwards?\n\nBonie Shupe (15:01): No, actually IEX 1.0, a lot of the head management gave Flower Fund a lot of advice and they had put together a lot of presentations and really recommendations for how to move the brand forward. And so when I came in and took the reins, I actually had to filter through all of that information. I also did talk with a lot of past employees and kept some on as consultants through this first part of relaunch, relaunching the brand. We do, we have a number of assets still from ivex and we had a lot of products. I think one of the things that really probably sealed the deal with me is as soon as I was in New York and I was unpacking all of the Ibex product, I was there until three in the morning just organizing it all and they left and went home and I stayed there and I was just like, I mean it was my dream job and here I was with all the product and I was just so happy to go through it and see all the iterations and see all of the samples from past years. So yeah.", "token_estimate": 491, "speakers": ["Bonie Shupe", "Cole Heilborn"], "start_timestamp": "13:57", "end_timestamp": "15:01", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "483bd677-0d0d-4a36-a14a-713eadbae23b", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 7, "content": "Cole Heilborn (16:19): One of the things that strikes me as really interesting is this, the 1.0 version had this really strong community, this really strong kind of entrenched community of followers and of advocates as you're moving forwards that's got to be kind of difficult but maybe also makes your job easier knowing that you have this support, but also knowing that you've brought the company back to them and now how do you not screw it up or how do you make it move in the right direction? What type of responsibility does that come with and how do you guys deal with that sort of pressure?", "token_estimate": 150, "speakers": ["Cole Heilborn"], "start_timestamp": "16:19", "end_timestamp": "16:19", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "37a3e5eb-7f1d-4b28-b096-587a01eeed2c", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 8, "content": "Jordan Todoroff (16:57): I think we have done a very good job. Bonnie really pioneered this from the relaunch was making sure that consumers knew they were heard, right? So the first thing was before anything was to recollect that community. And so I was also an IEX consumer. I sold it for another company in the outdoor industry previously, but I wore it. I loved the product and I remember receiving an email that said that IEX was going to be relaunched and I could be invited to this Facebook page, which has gotten 13,000 followers or something. It's a huge following of IEX Insiders. And then another secondary group founded itself called the IEX Junkies because people were obsessive. And so Bonnie really threw herself into those groups to get feedback and to stoke and ignite that excitement for the brand. If you go through, I mean if you type in ivex closed, you'll just see article after article that the comment sections are filled to the brand with people saying, I've got my pieces from 15 years ago and saying how sad they were. (18:04): That was their favorite brand going under. So we've tried to be really good about listening and making sure that feedback was heard by people. We're a brand of real human being people and we care about discussions and think collaboration is how we excel. Like we said, IEX is really founded on that idea of relationship and community and that was all the way from consumers, wholesale partners, international partners, the team itself. And some of that did get lost towards the end, especially with cutting off wholesale accounts. And we are still, I'd say the thing that we love most about Ibex 1.0 is relationships. We believe in working with people and being good teammates and good partners in this symbiotic relationship of making a brand and making a company. It's a huge team effort and there's no way we can do it on our own. So I mean, I respond personally to customer service tickets way too late at night, but we're entrenched. (19:09): Bonnie I know is responding to customer service tickets today and generally that's not something that falls within our types of scope for our roles, these job titles. It's very rare that you would have someone even acknowledge customer service tickets or even interact heavily with the customer service team. But I mean, Bonnie's gone out to coffee with people. I write to people on LinkedIn, I have phone calls with old customers and old partners and really just pouring into that to make this give and take a real open communication. And sometimes that communication is us saying, we're actually not going to bring that product back. We loved it too, but it wasn't functional. But a lot of times it's like, cool, we're so excited to hear it. You're giving us good feedback. We're going to start to build this up from here.", "token_estimate": 707, "speakers": ["Jordan Todoroff"], "start_timestamp": "16:57", "end_timestamp": "16:57", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "70730145-1210-4629-901d-0165a66ff615", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 9, "content": "Cole Heilborn (19:59): So two questions from that. Number one, why is there such a strong community, a legacy community from 1.0 and why have you guys made it a point to dive into that community and talk to people and take 'em out to coffee and send them messages and emails as you're launching 2.0?\n\nBonie Shupe (20:18): I personally think that the community was born well, one, because the people who ran Ivex really cared so much that it was obvious to all customers and they were drawn to it, but also because the product was more elite. And that is something that I have continued to try to push. I really truly believe that Ives brings the Merino product to the market and I will continue to push for that every day.\n\nJordan Todoroff (20:54): And I think iex also, when I think about the brand, one of the most iconic stances I think is that IEX was one of the early companies to pull out of. And they had a strong belief in a variety of things, but they weren't scared to take stances where they felt was important for the outdoors. They were original founders of early partners with the renewal workshop and with Conservation Alliance really involved in passion projects about their environmental footprint was huge for iex. They took it very seriously and they took defending outdoor spaces very seriously. And I think when you see brands of real people, like Bonnie was saying, it was a passion project. This company, it was founded, it was somebody's baby. And when you have a team that's so deeply involved and so passionate about their own love of the outdoors plus products that they want to use, they're actually and consumers of, it's something special and it's something you don't see very often. They were the stakeholders, right? At the end of the day, it was the product they wanted to use. And so they weren't pitching for someone else. It was the company they wanted to run, wanted to be a part of, wanted to purchase from. And having that big holistic cycle mix, a very different type of company.\n\nCole Heilborn (22:22): Yeah, interesting. And then the second question, why inject yourselves into those old communities?", "token_estimate": 536, "speakers": ["Cole Heilborn", "Bonie Shupe", "Jordan Todoroff"], "start_timestamp": "19:59", "end_timestamp": "22:22", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "2ba560fa-7f68-4d3a-bd0e-12b075d675d1", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 10, "content": "Jordan Todoroff (22:28): I was a part of the communities already, I think so was Bonnie and I both wanted to be hired by IEX previously. We both sought out employment with them. I have many old pieces from Ibex that I still wear. I still love people. I've talked to people's ear off about Ibex for eight years now, and those are the things that I care about. I'm an avid outdoorsman, I'm a passionate environmentalist and I'm obsessed with Marino wool. And so those three things come together to make oh and high quality goods. So you put those all together and in my mind, and so I, I talked to Bonnie for almost two years before I got on the team. I just was obsessed and I wouldn't give it up. And she was the same way. She's slugged along and put in a whole lot of hours because it's the stuff that we care about and we love. And so we were already a part of that community.\n\nBonie Shupe (23:24): I mean honestly, I'm an introvert and so getting on the insiders group and talking to the community is probably, it's one of the scarier things that I have to do with my job. But I feel like it's such an important thing because the community made the brand that that's why I'm there and I'm ready to listen. And like Jordan said, I've gone to coffee with different people, I've met up with other consumers who bring bags of IEX to me and show me this is the best year. And I have other people who I've reached out to on the insiders group and I'm like, you are obviously so passionate about our seamless, can we do just a little focus session? I'm going to send you a bunch of seamless product and let's go through it so that we can nail our seamless in the future if we have access to those communities. I didn't see a reason why not to use them.\n\nCole Heilborn (24:29): And moving forwards, how do you preserve what was created? But how do you distinguish moving forwards because there are differences, but how do you honor that in a respectful way?", "token_estimate": 488, "speakers": ["Jordan Todoroff", "Bonie Shupe", "Cole Heilborn"], "start_timestamp": "22:28", "end_timestamp": "24:29", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "80a0d465-0a80-4e89-8d9f-ebf41bd74c1e", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 11, "content": "Bonie Shupe (24:43): For me, it comes down to the product. So one of the things that we're going to launch, maybe I shouldn't be saying, but one of the things we're going to launch this year is Wool Air, just one of our rule air pieces. And for me it's like I think of Ivex as being the original innovators of Wool Air. They were really putting out those jackets before anyone else. And for me, I am rethinking wool air and how to make it better. I'm not starting a product from scratch. I'm taking old ivex pieces and I'm saying, okay, this was a heritage piece, it was a champion piece and then I'm rethinking it for today and how can this piece be more useful, become a hero product and be that product that everybody goes to and everyone should go to across all generations, across all end users. And how do we just push that forward and that narrative? And so I think what I try to do is really, it's not even try, I respect IEX 1.0 and everything they did so much. So it's really easy for me to take those products and then just try to make them better.", "token_estimate": 265, "speakers": ["Bonie Shupe"], "start_timestamp": "24:43", "end_timestamp": "24:43", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "6f8455b8-a54a-401b-8244-5d824969f939", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 12, "content": "Jordan Todoroff (26:10): And then we also as a team, we all came together, so in New York and we sat around a table for hours and hours and hours and dissected what ivex was, right, who was this company and what made it what it was. And we took that distilled information and we built it into what we internally we call our brand pillars, but we took those real core essential elements of what made the company work and what made it special and make sure that our decisions are interpreted through that lens. So consistently we've go to make a decision, we run it against this litmus test that we've built for ourselves to say, is this IEX and does this speak to the core values that made this company so special and made it work? And we also, part of that was trying to analyze what didn't make it work, but I think having that SIV essentially to filter out what is an ivex idea and what is a personal idea is really formative for us as well because everybody wants to contribute to the brand they love. (27:17): We all want to say, I've got this idea and I want to pitch this and I've got that idea. But ultimately for a brand to be effective and for a brand to maintain its core central identity, it's either a founder, CEO who stays with it and is always at the helm and never leaves, or you allow the brand to speak for itself and make its own decisions. So we've worked really hard to make sure that that has stayed at the forefront. So kind of like Bonnie said, we can take all those core values and translate them today to what's most relevant.\n\nCole Heilborn (27:48): I'm curious then of the core values you identified with 1.0, did you add or change any for 2.0?", "token_estimate": 418, "speakers": ["Jordan Todoroff", "Cole Heilborn"], "start_timestamp": "26:10", "end_timestamp": "27:48", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "5ca705cd-a032-492b-aad6-d638ff6c3447", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 13, "content": "Jordan Todoroff (27:57): So it wasn't necessarily that they did have some written core values. I'd say they changed over time and developed. So we wrote our own built upon those. Yeah, I won't bore you with all of the details because they're fairly lengthy, but they're essentially the idea that the garments are made to last. That's an important one for us, that there's a real timeless aspect, I think is a real defining characteristic of the first IEX iteration mindset over a skillset is also kind of developed from their original iteration, but it's the idea that we work with people who love the outdoors and who care about the things that we care about. So you make this, not only do we have a community who's already there, and I totally misspoke, it's 8,500 people in the insiders group, but not only do we continue those people, but when we make partners, we try to choose partners who share the same values that we have. (28:57): Stewardship is absolutely a core value for us, and that's our social impact, that's our environmental footprint. It's a huge variety of things. And then masters of materials and innovation, we want to be at the forefront of developing things. And you know what? Sometimes that means that you swing and you miss, but man, we're going to try. We care about being the best and making new things. And that's like that pioneering spirit is very core to iex. So I'd say we built upon even some language they had originally, but it was just trying to distill old writings, old discussions with previous employees about what they loved and the consumers themselves. And that's what we found to be the most central ideas behind the brand.\n\nCole Heilborn (29:40): Okay, gotcha. Was there any luggage attached or any bridges that had been burned that you've had to overcome?", "token_estimate": 451, "speakers": ["Jordan Todoroff", "Cole Heilborn"], "start_timestamp": "27:57", "end_timestamp": "29:40", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "45fb456b-769c-482e-8d72-3d6f58879ef6", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 14, "content": "Jordan Todoroff (29:48): Yeah, I should say so. And there are articles written online about why you shouldn't do business with iex. It's literally articles written, why don't be like iex. I think I come from a pretty interesting place and it's part of the reason that Bonnie and I are really kindred spirits. We're such a great team and I feel really lucky to work with her all the time. But she brought me in because I have a background in retail myself. So I worked my way up from a part-time stock associate to a store manager. And I understand why it's so important to have great partners in wholesale. I also understand the immense amount of work that retail employees put in on the ground floor, getting consumers excited about the products they buy and making sure they buy the best thing that they can for their needs. These guys are hard workers, they're underpaid and they add so much value and they're good teammates. (30:43): I feel so lucky to have worked my whole career in retail. It's hard work, but I feel lucky with so many people I've met and the types of work you do all that to say Ibex towards the end was not a good partner to their wholesalers. They made a last minute decision and said like, all right, cool, it's done. And when you rely on that, those buys that you've made originally for your own company's finances, that's a huge slap in the face and especially if you've worked with someone for almost 20 years. So I feel excited to come in and I've had a lot of conversations with these shop owners and say, my first thing is just apologizing. And while it wasn't my mistake, right? Well, we didn't make those decisions for the first iteration of Ibex. I'm still sorry for what they did because I've experienced those kinds of things and it's pretty devastating and it's hurtful and it's pretty disrespectful. (31:43): And our goal is to be respectful, good partners who can under promise and overdeliver. So we are currently slugging through that. There are conversations, I have people who don't even want to talk to me and I tell them, I totally understand. I hope we can grab a beer sometime. I get it. It wasn't my mistake, but it was still something that was so offensive. And so we work with on the production side of things, on the wholesale side of things, essentially what we've said a lot of times is that the only person burn was their customer", "token_estimate": 597, "speakers": ["Jordan Todoroff"], "start_timestamp": "29:48", "end_timestamp": "29:48", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "27ca5d17-a629-4d4b-a7e1-3fc7c75359b4", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 15, "content": "Bonie Shupe (32:18): On the product side. Yeah, we lost a lot of our manufacturing partners obviously because we closed, so we kind of lost that relationship. We didn't have a lot of the same materials. We're not able to access some of the favorite materials that people want back. And so I've actually had to start over and start from scratch and redeveloping materials and in order to redevelop some of these products that people really love. And also just gaining the trust of the IEX insiders. I don't know that I've gained everyone's trust, but that definitely, I know there was a lot of hype when we first relaunched and everyone was so excited and then people were so disappointed. (33:10): I did ask me anything session on the insiders group and left that and cried. There's been a lot of that because it's like I'm working from the same place of passion and love for a brand and people, they want their old IEX back. They don't want me and Jordan, but we're here and we're taking the helm, so hopefully people will grow and adapt to us. You know what? And then there's other people that reach out and they are just so grateful that we're bringing back this brand that they love and that we brought back the shack jacket and the hoodie and the shack vest and that more products are on their way. And people write in and ask me about certain products and give me feedback all the time. And so the baggage has a double-edged sword I would say.", "token_estimate": 363, "speakers": ["Bonie Shupe"], "start_timestamp": "32:18", "end_timestamp": "32:18", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "dbb5d384-f975-46e8-ae79-a61bb3b7cee5", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 16, "content": "Jordan Todoroff (34:08): Yeah, people are pretty polarized. And like I said, I work with our customer service team and I see both sides of that. So I see the folks who are like, I think people don't understand that once a product is fully designed, which is an incredibly arduous process and takes the amount of products that have been designed, and then at the last minute we've said like, Nope, we want this product, but it's not iex and it's not where we should be right now. I mean designing products that don't go anywhere. So there's so much time and effort and energy that's put into that. And then once that's all done, everything you've picked your supplier, you sort everything out, it's like 165 days to just make the product and then it still has to be shipped to. I mean, it's such a time intensive thing and people want their products that they loved and they want them now, and it just takes time. (35:06): We're coming in from, we haven't been founded for 20 years and we're building on a legacy of that and have some of those assets, but primarily we're having to, when we burn suppliers, we have to find new suppliers. And Bonnie's like time and time again, rejected textiles that we've worked to try to redevelop because they weren't to standard. So people want this particular fabric, but they don't understand there is one machine in the world that made that fabric and that machine doesn't exist anymore. And so someone has to rebuild that, reine it, redesign it, and that takes time. And we have really high standards for what we release with ibe X's name on it. We care about that. We talk about that made to last pillar. That's one of those things. And even if we love it, and even if it's a product that we as individuals really want, it has to meet that. (36:00): It has to pass that litmus test. And so on the one side, people want things and they don't understand why it hasn't come back yet. But then on the other side, we also get people who realize we've rereleased products with higher quality textiles than they ever were textiles that are, you don't find anywhere else in the world. And we've had people say, oh my goodness, this is better than any IEX product I bought in the first 20 years. I just bought five. Someone bought five of the same jacket. They've spent a thousand dollars on jackets. And that is incredible. That's my dream is that every ratty jacket that you don't want to throw out and it's been 15 years and your partner's upset that you still wear it out, is an IEX jacket because somebody never wants to part with it. They just want to keep it forever. (36:45): So that's what we're working really hard towards. It takes time, it takes effort to refine and develop, and we're trying to push the forefront of technologies and that masters of design innovation. And that takes time. It takes time to develop new textiles and new designs, and we understand that people are chomping at the bit and they want it and we also want it. We put in a lot of hours to get there. So we're excited to celebrate when things are released with people and we get a lot of excitement when new products come out. People are waiting for it. And particularly when you think about it, IVEX was refound at the end of 2019. That's a hard time to relaunch a company given the start of 2020 was the pandemic. That's what IEX has refound under. And so it's been an additional set of challenges. I'd say overall the community is passionate and that I'd take that any day over a set of folks who don't want to be involved. So we're excited to have them involved, but it does take some time to get people back on board.", "token_estimate": 911, "speakers": ["Jordan Todoroff"], "start_timestamp": "34:08", "end_timestamp": "34:08", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "accd410b-18f9-498b-8f14-8e6821c12362", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 17, "content": "Cole Heilborn (38:03): Some people have been hurt, trust has been lost. And that just takes time. It takes time to build trust. Unfortunately, trust can be broken very quickly and to rebuild it, it takes even longer. Certainly. Why will 2.0 be a slam dunk? Obviously there's a lot of things that are different, but if there's anything specific that you could point to other than just new people, why will it be around for another 20, 50 years?\n\nBonie Shupe (38:30): I can tell you lie right now in the Marino space, for example, what we have currently is we have our top leading brands that have been around for a really long time, and then we have all of these new Merino brands that are coming into this space and they're rushing into the space. And those Merino brands that are rushing into the space right now aren't developing new textiles. The ones that are leading the space, they're at a point right now where they're trying to figure out how they can get to a bigger mass audience. And so I currently don't think there is a huge Marino player who is outdoor focus and quality focus. And that's what Ivex is doing, unlike any other brand on the market. And so right now, when I'm looking at all the Marino and I do my SWOT analysis, I looked at the space as a whole and I said, oh, well we are key players in that we are innovating textiles unlike anyone else, and we're using the highest quality Marino and we're doing it sustainably. So all of those three things all play together, and I think that we're going to be slam dunk. We are a slam dunk. We're just building momentum.", "token_estimate": 397, "speakers": ["Cole Heilborn", "Bonie Shupe"], "start_timestamp": "38:03", "end_timestamp": "38:30", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "d447cb32-7de1-4562-8dd5-93d116897871", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 18, "content": "Cole Heilborn (39:51): Well, and it's awesome to hear that you're building momentum and you're taking it one day at a time or one step at a time. But I'm curious, why have you guys chosen to be involved with this revival? I mean, you're talking about all the pressure pressures that you face and all the challenges that you face, and they're not, I mean, some of 'em are unique and reflective of just a startup business, but you also have this added complexity of the legacy that you're taking on and the repercussions of decisions that were made before you. Why sit through a Facebook q and a and then cry, but feel like you're doing the right thing?\n\nBonie Shupe (40:33): That's a really good question. For me, IVEX was the most iconic of the Marino brands. They were city to slope before it was cool. Part of why I wanted to switch careers and go into the apparel and textile space is also because of the sustainability issues that were happening here. We were outdoor people and we are consuming goods that were not good for the planet. And so when I decided to do that and went down this path, IVEX was always in my mind because they were doing things in that right direction and they had that momentum all of this time. And so when the opportunity presented itself, it was, I was actually pretty happy with what I was doing. And when the opportunity came, I knew I had to make this leap, and I knew that I had to take my introvert self and become this person for this brand because it was, it's everything that I have ever wanted in my career.", "token_estimate": 388, "speakers": ["Cole Heilborn", "Bonie Shupe"], "start_timestamp": "39:51", "end_timestamp": "40:33", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "58a8b9f5-d7a2-442f-a0a0-e9cad9816118", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 19, "content": "Jordan Todoroff (41:52): And it's just like Ibex champion things that I think we both believe in and that we are grateful for and love. So to be able to be a part of championing that as a job is pretty exciting to me. I would definitely say part of the reason that IEX 2.0 is already successful and will continue to be successful is that it's so much more than a job for us. I mean, Bonnie and I stay up late just arguing about the use of certain textiles and the greenhouse gas emissions and the environmental impact and how to curb that and do the best that we can. We're a climate neutral certified brand and we're incredibly proud of that fact. But it comes with a lot of work, a lot of arguments about the types of packaging that we use and how to reduce that. And so we have that, but then we also are passionate outdoors people. I'm actually moving out to Netherland in August to make a headquarters and to build this alongside Bonnie, and she sold me on it by forcing me, I mean forcing me to hike every single day. She told me, she's like, when you're out here, we're going hiking every single day, so you want to live here. I thought, that's the company I want to work for. (43:10): It's not a blind business that has little investment in the end product. We are using the product. There's so many things that I want from IX 1.0, same as our insiders. I'm like, I want that product back. And we're testing it and pushing it. The stuff that we want to use, it's made in a way that we're incredibly proud of. We treat people fairly and with dignity. We respect our partners and we just want to make the best stuff. We're also willing to, she making products that we love and we're excited about until they're right. And so it has this much more honed, I think that Ivex 2.0 has a lot of direction. We have a 10 year plan laid out for ourselves, and we know where we want to be and we know how we want to get there. And if nothing else, damn, have we got a lot of grit?", "token_estimate": 494, "speakers": ["Jordan Todoroff"], "start_timestamp": "41:52", "end_timestamp": "41:52", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "15ecc01c-caaa-4fe9-a1e9-6e215d41fc9f", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 20, "content": "Cole Heilborn (44:07): That's well said. A couple more questions. Jordan, I'm curious, so you're picking up your life in San Francisco or the Bay Area, moving for the job. You said the job is so much more than a job, but through the job, what lessons have you learned? I don't know about life, about yourself, about others. Is there anything that stands out?\n\nJordan Todoroff (44:30): Yeah, so I worked in retail for a long time, and like I said, it's a hard line of work. I've been clubbed with roofing hammers. I've had people chase me. I've had a lot of things stolen. I've worked a lot of long hours and showed up late in the night when my store was broken into or early in the morning. I've had people yell at me, but I've also had people hug me and I've learned how to respect people and understand that when they're upset, maybe it's not anything to do with you. All that to say, I'm in a very different role now than I was as a store manager and I've had to pivot a lot. But what I've realized is the core values that I learned of great customer service and building a business the right way, being willing to do the legwork, to not cut corners, to treat everyone you work with respect. (45:24): I just earnestly respect everybody that I work with at Ibex and retail workers are like, they're just kind of known those guys are running all day. And I did not expect to find people who outworked me. It's pretty rare. I tell that to my employees all the time. On day one, I'd tell my employees what I made in retail. I wasn't scared of that. And I said, because you're never going to outwork me. And I found a community iex of people who could just, I don't know how they do it. Bonnie runs an ultra marathon every day at work, and I'd say our whole team does. Our owners are absolutely slugging along just as much because we have so much passion. So I've learned that being able to mix that, just that core sense of respect for your partners and your customers and deeply caring about that and being willing to say, I'm wrong. (46:12): I messed up. I want to do better. And keeping open communication has been huge. We don't care about being right. We care about doing what's best. And I'd say a lot of that was like did come from my retail background, being able to say when I was wrong. And part of the reason I wanted to work for Bonnie is that she told me she took a fail first approach. I love that we are absolutely willing to embody that. And so personally, I've learned how important that is to be okay messing up and own it really quickly. And then as far as the sales perspective, it's just same kind of thing. It's relationships. All these guys who we care about. I've just reached out to old iex partner after old IEX partner, and for the most part, when I tell 'em my background in the industry and how I love the same things that IEX 1.0 was about, they're on board. They want those relationships. Human beings are, as much as we're changing and developing, technology is so crazy. Humans are the same as they've always been. We care about good relationships with people. We care about good communication. And fortunately for us at iex, we love the outdoors. And so such a great point that we can all get behind. So just meeting people on a human level. And I think being a company with a face means a lot to me, and I think it resonates with a lot of consumers.", "token_estimate": 846, "speakers": ["Cole Heilborn", "Jordan Todoroff"], "start_timestamp": "44:07", "end_timestamp": "44:30", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "1a29fdb7-925f-4c5b-a0cc-eed3f8a93a8e", "episode_id": "3fac7ad1-932e-42e6-89bd-72c48700663d", "cms_item_id": "68225dfc7bb476527f8c486d", "chunk_index": 21, "content": "Cole Heilborn (47:35): Bonnie, as an introvert, I can relate. I'm curious, what specific challenges have you had to overcome as an introvert taking on this job? You've mentioned talking to community members, being the face for the company, being on podcasts, whatever. I got to imagine there's some friction there for yourself personally as you're putting yourself out there.\n\nBonie Shupe (47:58): Yeah, there's a lot of friction. I would like to just sit home and design all day. But again, it's like, again, relationships and relationship management. It's funny. I often say that I do all my GM tasks during the day and then I get to product at night. And I am really lucky that my partner stays with me during this time because yeah, I feel like every day for all of the hours that I work, it's all about relationships and relationship building, which is very different from what I've done in the past, and I'm getting better at it every day. But it's definitely hard. It's definitely something I'm overcoming.\n\nCole Heilborn (48:51): Yeah, yeah. Well, guys, I just want to say congrats and keep it up. Sounds like we could all use a pat on the back a few times every so often, but I'll give you a virtual pat on the back right now. So I want to thank you for your time today coming on the show. I had love to keep chatting, but we're kind of coming up against the end of our time. If folks want to follow along, if they want to learn more about iex, if they want to follow along with you guys personally, where can they go to connect?\n\nJordan Todoroff (49:22): Yeah, so we've got Instagram jump on head to Ibex X's website. I mean, I think you'll learn a lot about the story and what makes us who we are. We try to be pretty passionate about that, and we're working our way into wholesale sooner than people are expecting. I'm hoping. And we will be an outdoor retailer. If anybody wants to swing by and give us a chat, by all means, reach out, shoot us an email, and hopefully you'll be seeing a lot about us. We're starting to pop up left and right throughout a lot of different publications, and we're excited about that. So people will be seeing a lot of iex.\n\nCole Heilborn (49:55): Wonderful. Well, guys, thank you again and I hope you have a great rest of your day, and we will chat with you guys soon. Right on. Thanks so much, Cole. Yeah, see you, Jordan. Yeah, thank you. Bye, Bonnie. Cheers. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 654, "speakers": ["Cole Heilborn", "Bonie Shupe", "Jordan Todoroff"], "start_timestamp": "47:35", "end_timestamp": "49:55", "podcast_index": 70, "episode_name": "EP 70: Bonie and Jordan | Re-Launching an Iconic Brand | Ibex", "slug": "ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "web_url": "https://www.portsidepro.com/podcast-feed/ep-70-bonie-and-jordan-re-launching-an-iconic-brand-ibex", "guest_name": "Bonie Shupe and Jordan Todoroff", "guest_title": "Ibex", "categories": [], "short_description": "Ibex used to be a beloved brand that championed Merino Wool technology and was passionate about its climate impact. These two elements created an undying community of users who loved their Ibex clothing.", "podcast_length": "44:92"}, {"id": "c1984f50-e8bb-4e20-bfd1-b6a392bcf3c1", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 0, "content": "Dave Taylor (00:01): It is a lot easier to be cynical about the other work that's not very good, rather than really being a fan of the work. That's good. And that's how you're finding yourself in your place in the world. And that can end up being detrimental because spending a lot of your time in this negative place where it's even looking at really good work, you're like, oh, they only got to do that work because they're so-and-so working at this place, I can do that myself instead of taking a step back and being like, and appreciating the stuff that's out in the world for what it is versus everything that's out there.\n\nCole Heilborn (00:33): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with Dave Taylor. He's the founder and creative director at ok Bro. Dave, how are you doing?\n\nDave Taylor (01:14): I'm good, man. Thanks for having me.\n\nCole Heilborn (01:16): Yeah, thanks for joining us. Where are you calling in from?\n\nDave Taylor (01:19): Seattle, Washington.\n\nCole Heilborn (01:21): All right. Another Pacific, Northwestern.\n\nDave Taylor (01:23): Yes.\n\nCole Heilborn (01:25): Well, I'm super excited for you to join us on the show. First question, what do you enjoy doing outside? What are your hobbies? What would you do on a Saturday?", "token_estimate": 468, "speakers": ["Dave Taylor", "Cole Heilborn"], "start_timestamp": "00:01", "end_timestamp": "01:25", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "ef7f3313-12d4-449b-b254-b3eb8e406c00", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 1, "content": "Dave Taylor (01:37): Oh, in the year round, it is generally hopping on the mountain bike either with my buddies or my fam, and in the winter it's heading out and open for a cow day. And then this time of year we usually, me and the FA usually go find a spot for huckleberry picking, and then once the fall hits, we go mushroom foraging, got to get them CREs.\n\nCole Heilborn (02:02): Nice. There's not too many mushroom fors out there. I'll make it like once or twice every fall, but it's good to know that there's someone else out there.\n\nDave Taylor (02:12): Oh yeah, it's the good stuff. You got to be careful. Don't tell anybody your spots, but my kids are actually really good. They're closer to the ground, so they have a good eye.\n\nCole Heilborn (02:23): Yeah, they probably, they don't mind all the cobwebs in their face nearly as much as you or I might. Well, I'm super excited to learn a little bit more about OK Bro, and some of the work that you guys do. So to kick us off, could you kind of give us a little bit of a background on the company?\n\nDave Taylor (02:41): Yeah, well, OK Bro is a branding and advertising agency with a real strong focus in graphic design. The company is just me. We have a pretty broad range of super talented collaborators that we work with, writers, web developers, producers, filmers photographers, et cetera. We like to work with brands that are making the world a smarter, cooler and router place to live in and focus on things that we care about and want to work on.\n\nCole Heilborn (03:15): And I think you kind of kicked us off for our topic for today, which is talking about company structure and all of the things that permeate from that topic. Before we jump into that though, I'm curious if you could give us some background on some of the projects that you've worked on, some of your experience, and when did you start? Okay, bro.", "token_estimate": 471, "speakers": ["Dave Taylor", "Cole Heilborn"], "start_timestamp": "01:37", "end_timestamp": "03:15", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "9aceef90-c7dc-439e-bc11-a50a497f4d12", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 2, "content": "Dave Taylor (03:39): Well, I guess we could start, we'll go chronologically in some way. Way back as Baby Dave, I landed a job as a junior production designer at an agency called Christopher Porter Guskey in Miami, which at the time was about 45 or so people. And we were working on things like Truth, which was the anti-tobacco campaign in just Florida at the time, as well as a number of bike brands. The ECD of the company is an avid mountain biker, and so got to work on Schwinn back in the day, Shimano gt, et cetera. And then that agency grew and I started becoming an art director. We launched the Mini Cooper in the United States when that got relaunched. And so it was really interesting experience watching this company go from 45 people in Miami to now it's about when I left there, there's a few hundred and now it's thousands of people around the planet, which is wild to be part of that in the very genesis of it. (04:39): From there, I bounced around just a little bit, landed at a great place in Madison, Wisconsin called Planet Propaganda, where I'd say I kind of grew up in the industry a bit. I led creative for Gary Fisher for about eight years doing catalogs and advertising videos, et cetera. And because of that, that really got me really deep into the mountain bike world and started traveling to all these amazing destinations with a level photographers. And then I'd go home and ride my home trails in Wisconsin, which while the access is great and they're fun, but when you're getting to ride on the north shore of Vancouver for a photo shoot, then you go back to Wisconsin, you're like, okay, I need a little bit more. Which then led me to moving to Seattle and bounced around to Seattle a little bit, did a stint at Amazon doing product launches globally. (05:38): So the scale of work that I was doing there was just massive, was a huge amount of education that happened during that time. Got recruited out of there to a small agency that was starting up and got to work on stuff for Frito-Lay and Mr. Coffee and a lot of more mass brand stuff. And that ran course. And I was just thinking about, well, what exactly do I want to do with my life now dad with two kids and a wife to support in a really cool city in a great place and wanted the most amount of flexibility to do the kind of work that I wanted to do, go get a powder day when I wanted it, and if the dirt's good, I could go bug out for a morning or an afternoon and go for a bike ride. And that's really the genesis of where I started. (06:26): Okay, bro, is it was really a lifestyle choice and the type of work and the type of life I think are kind of melded together quite a bit for me. And I think for a majority of creatives, they're almost one in the same in some way how they influence each other. And I wanted to see what I could do about taking the most amount of stress from the workday out of the equation. And now I'm what, almost five years? Well, a little more than five years deep as okay, bro. There's been some ups and downs and more people a part of the company than there are today, but the future's looking pretty good.", "token_estimate": 783, "speakers": ["Dave Taylor"], "start_timestamp": "03:39", "end_timestamp": "03:39", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "b7bc6a34-360f-4e18-89c6-5e910a01b713", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 3, "content": "Cole Heilborn (07:05): And the name, how did the name come about?\n\nDave Taylor (07:10): So when I was at my very first job at Kristen Porter, I was actually working on just coming up with some T-shirts to express, making fun of that Miami bro culture, which is vastly different than what we think of bro culture here today, which is it's very mountain bikey I guess in some ways. And very, or just very drunken frac guy is the bro these days. But back then it was like lowered Monte Carlos and tight Edwin jeans and lots of bass and I love that stuff, but bro is like the third word at everybody's out of all those guy's mouths. And so I just started ok bro. And that became our freelance moniker and somehow had the foresight to buy that URL on 98 or 99, and somehow that credit card never expired. Expired. And I still have it today. The cool thing about doing it right now is it turns every presentation into not a me versus you or a business type of thing. Everyone becomes human because you have a silly word up on a big screen in a fancy conference room. And so all of a sudden CEOs of companies are just like, the walls come down very simply, very simply than if I called it, I don't know, made it sound like a law firm.\n\nCole Heilborn (08:38): Sure, yeah. Dave Taylor's branding and design agency.\n\nDave Taylor (08:44): Exactly. Or marketing services or something\n\nCole Heilborn (08:48): Like that. There you go. No, I love that. That's pretty awesome. And you recently wrapped up a with Diamond backed, excuse me, your get amped campaign. How did that go", "token_estimate": 391, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "07:05", "end_timestamp": "08:48", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "970f5f95-566d-4e05-b63f-c2c96a4749cb", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 4, "content": "Dave Taylor (09:00): Really well, it was one of those projects that came through and I had been talking with Evan Moss, who's a creative director over there for, I dunno, probably about four or five years. It's actually one of our first meetings that I had at OK Growth to do new business. And finally all the cards lined up and we got to collaborate on this project, and it was one of those where I kind of got to pull out everything that I enjoyed doing from top to bottom. So that project was a launch for their new line of ebis, and so we had to understand what the category was, dig into the DNA of what Diamondback stands for, where Diamondback comes from, develop messaging that'll work for this new category both visually and from a communication standpoint, and then come up with a really fun launch campaign. And so it's like from the foundational aspects of developing this new category for that brand all the way to trying to get as much attention for the launch as possible.\n\nCole Heilborn (10:08): Yeah, Evan and Jill, they're great people over there. Jill was actually on the podcast early last year, maybe like episode 15 or 16, and we talked all about her role managing the five or six different brands that Alta cycling manages, and I highly recommended if folks are interested in learning about how to differentiate between brands and whatnot. But no, it was great to see that project come out and that's actually how we got connected and one conversation led to the next, and now here we are. So I guess we can thank Diamondback.", "token_estimate": 388, "speakers": ["Dave Taylor", "Cole Heilborn"], "start_timestamp": "09:00", "end_timestamp": "10:08", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "159e29a9-9744-48ad-9b6b-6dca015da0a2", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 5, "content": "Dave Taylor (10:40): Yeah. Yes, and shout out to Jill and Evan. They were an absolute dream to work with, and it's one of those things where if you get some really smart like-minded people into a room together, really cool things can happen, especially the level of smarts that they bring to the table, both from a strategic standpoint, but also just the willingness to get their hands dirty, to make things happen. And the resourcefulness that they had, and I got to bring to the table as well, I think created one of those really sweet campaigns where it's so much of the time, we'll present work for a campaign launch that has a lot of interesting little activities that help bolster the entire thing. And as so much of the time because of bandwidth or just the willingness to roll their sleeves up, clients will let those things fall through the cracks. (11:34): But in this project, pretty much all of those ended up happening. We did this huge video. I'm really proud of the work that came out. One of my favorite things that we did was we sent pinatas to bike shops and that were filled with swag, and if they smashed the pinata and put it on their Instagram, they got entered to win a pizza party for that bike shop. That's one of those things where, yeah, there's a bunch of logistics that need to happen to make that go off, but it's one of those things where you could hit all the different touch points that they need to. It helps with the success of the campaign.\n\nCole Heilborn (12:10): Yeah. Oh man, that's cool to hear. So you alluded to it earlier, you said in your introduction that, okay, bro is a company of one. Let's dive into this. I think there's a lot of questions around freelancers turning their business into a business and making that transition between freelancer to agency owner, but I haven't seen a whole lot of resources out there about how do I structure my business? How do I want to think through what my business looks like? And so I'm curious to hear from you, how is your company set up and why have you chosen to set it up this way?", "token_estimate": 519, "speakers": ["Dave Taylor", "Cole Heilborn"], "start_timestamp": "10:40", "end_timestamp": "12:10", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "bc7491ef-ab0a-484c-9677-41b8fc3d5959", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 6, "content": "Dave Taylor (12:48): The key reason why I chose to set it up this way is keep the billings high and the overhead low, right? Because especially when you're starting out on your own, there's a lot of ups and downs that you need to be able to carry yourself through. There's going to be a month where you had four scopes go out and nothing come back or happen on time and things get pushed back. You need to be able to deal with that, especially when you're starting out. And then there's other months where, holy cow, everything happened. We're completely pinned and we're going to make a year's worth of money and six weeks. And you need to understand to be able, how you can weather those things. A big key to making sure that you're successful, I think as a solo entrepreneur is not to do everything yourself, but find great partners who are experts in what they do that you can trust and you've worked with before. (13:48): And I'm not just talking about producers and writers and other illustrators and other creatives. My favorite person on the planet is Vic at Ranta Accounting, who I pay a monthly retainer two to help me with my invoicing and taxes, bookkeeping and all those types of things. And it just keeps everything on track. And it's one of those giant monkeys that is always on your back as an independent company that you don't have to worry about every single day, right? We touch base every week, we see E, I get my p and ls from him at the end of every month, and we touch base and having an expert like that that has a network that I don't have, which then helps you find things like lawyers and mortgage brokers and insurance brokers, because out of the blue, one of your clients might say, in order for us to renew your MSA, now you need $2 million worth of business insurance. (14:50): Ask any solo designer starting out what that actually means and how much that costs or how you can even find a reputable person to do that for you. That's an entire day's worth of work. So you find those people that can help bolster your business that do what they do well so that you could do what you do well. And I think that's part of the key. And what that starts to do is that brings a lot of value to your clients because it's totally fine for me to pick a small few thousand dollars project where we just need some lightweight creative strategy because the client's in a rut, they don't have time to come up with stuff. Let's just do three or four brainstorming sessions with an output of X, Y, or Z. If my company was 15 people, that's not a profitable way for me to spend my time. But with a small company, I have 25 years of experience working for large companies and small companies across a whole bunch of different industries. (15:52): I'd say that's valuable experience that normally a client's not going to get because when you go and hire a larger agency, that ECD, which would be my job at some agency that I worked at, you might see me, if you have 300 hours of scope, you might see me for five or six hours of that scope. And everyone else there might be super talented, but you're not going to get that same level of experience and guidance from someone that's in ECD because there's just that time to do it because they need to. Their billing is really high, but it's also spread out across five or six people.", "token_estimate": 836, "speakers": ["Dave Taylor"], "start_timestamp": "12:48", "end_timestamp": "12:48", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "feaa2399-549a-426f-96ca-66e9a86e2c0c", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 7, "content": "Cole Heilborn (16:32): Sure. Gotcha. So what does your model look like now for an average project? How many are you working with contractors? You said you don't have any employees, correct?\n\nDave Taylor (16:43): Correct, correct. At the moment, don't the goal. I think over the next two years though, I'd like to be about three or four people. (16:53): It is the goal. But how projects work today, it really depends on the project and the depth breadth of it. For example, I restrict for one of the many sectors within the world of Amazon, and in that one I contracted out a writer as well as another designer. And so we tackled this together as a team. There was naming as well as visual design that's associated with it. And for a project with Amazon, they're really about option value and not deep thinking and ideas because they move so quickly, they don't have time to really dig into those things for a client like that kind of staff accordingly. Whereas the Diamondback project, which had a lot of different moving parts for that one, myself and my copywriting partner partner, we split this project up into two phases with Diamondback. So the first phase was conceptual development, and the second phase was production. (17:49): So what are we going to do? How are we going to go make it happen and then making it happen. So that first part was really just myself and my copywriter, concepting and ideating, and then myself doing a large part of the design work and collaborating with Evan and team to start to bring those things to life, and then helping them sell that whole thing internally. And so that was from the entire creative strategy. What are all the different launch tactics that we want to work through? Are we going to do teasers? Are we going to do swag? Does video make sense? How is this stuff going to land on their website? Coming with all of that type of thinking first, and then through that whole process, they're getting a good idea of what the budget is. And then once we got into the world of executing, then the team grew exponentially because we needed to produce this video. (18:46): So I have a dear friend who's a level executive producer who created that entire team. We brought in a director and a DP and an editor. We had a crew about 25 or 30 cruising around downtown Seattle. Overnight. We were shooting the video, and then we had a series of posters that we needed to create. And so hired a couple of really great illustrators to bring some of those ideas to life because as you're doing something that's across what three different categories, if everything looked like it was done with my hand, you're not going to have that extra bit of difference. So we hired a couple of different illustrators, and then we also hired a photographer, para scores, who's in Bellingham where you are, and he brought in on a producer and some talent. And we did that whole photo shoot over two days in Seattle as well. So it can expand really large very quickly, or there's other projects where it's just myself in my studio banging away on stuff.", "token_estimate": 770, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "16:32", "end_timestamp": "16:43", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "276cec64-db17-4a1d-b870-df880c6b5776", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 8, "content": "Cole Heilborn (19:51): So essentially one of the benefits that you're describing is that you can scale regardless of the jobs need.\n\nDave Taylor (19:58): Yeah, definitely. And I think you're really similar to any other big air agency. When you hire a bigger agency, depending on the scale of the project, you're still really only getting a dedicated crew of three or four people. You're going to get an account manager, a project manager, but that project manager's job is really just to move it through the agency across all their other projects. And then you have a core team of creatives, usually a copywriter and an art director who are thinking about your business or the project every day. And then there's layers of approval. So then there's an A CD and a design director and a creative director who are just popping in and out for meetings, guiding the direction of stuff. So really when it comes down to it, you're still kind of getting with this tiny agency, the same people that you would get. They're the same number basically that you would get at a larger agency. Now where it gets a little bit different is let's say Nike called Nike has a basketball division, they have running division, skateboarding, et cetera, et cetera, et cetera. And each one of those things needs a dedicated team to work against those pieces of business. And if they don't have the layers of people above that, then there's no continuity across all of those different things people need to focus on.\n\nCole Heilborn (21:18): I see.\n\nDave Taylor (21:18): Whereas a lot of the scale of the work that I do within the outdoor industry, most outdoor brands are not even close to the scale. Even one of the sectors in business in Nike, it completely works because there just isn't the amount of marketing need and creative work for it to make sense to have that many layers and that many people working on it.\n\nCole Heilborn (21:40): Gotcha. So you're saying at a certain point your model doesn't work for businesses that are extraordinarily huge, but there's kind of a sweet spot for your model?", "token_estimate": 520, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "19:51", "end_timestamp": "21:40", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "bfd6d635-811e-4332-9878-5b1a1313ff0d", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 9, "content": "Dave Taylor (21:54): Yeah, there definitely is. And it's interesting because some of those larger companies like Amazon almost works as a whole bunch of tiny companies that ladder to the larger one. I mean mind, some of those little pieces of business are absolutely ginormous, but the scale and the way that that company works suits my company really well because quick, they need smart thinking really fast because everyone at the company that I've touched or worked with has a very high capacity and tend to be whip smart and have very high demands. Whereas working with the smaller brand, like say a Diamondback or even some of the sectors within Specialized, which I've worked with, it makes a lot of sense because it's just you have a partner that you could call. You have a one-to-one relationship with the person that's guiding the work. And so when my clients call, we could come up with a solution on the phone because you're dealing with the person making the work. (22:58): Whereas in some of those other places where you're dealing with a slightly larger agency, it's like, okay, you talk to the project manager, there's going to be a meeting. There might be two or three days until that meeting could get scheduled da. And so in today's world where things tend to move a lot quicker, we can move a lot quicker. And it's not because we're using buzzwords like nibble, it's because there's a phone that you can pick up and actually talk to the person doing the stuff, which also helps when you have a lot of companies, even smaller ones are bringing a lot of the day-to-day design work they can because 25 years ago, in order to bring, or 20 years ago in order to bring that work, a huge investment for graphic design costs five or $6,000. And now you could do that on a computer that costs 1500 bucks. (23:52): So just like the numbers alone makes it easier, let alone how easy it is for someone to get to that base level of competency of being able to do some work. And so there's a real, and that used to be how agencies and design companies used to make a lot of money, have this blocking and tackling type of work that was just ongoing billable retainer level work. And then you pop in every few months for a new campaign initiative where you need that strategic thinking. And so the strategic thinking is difficult for someone to do. You need that outside perspective, whereas the blocking tackling work, at some point, it's almost assembly line work. We have images that need to be set up and retouched to go onto our website. Do you need a great strategic creative director to manage that work? Probably not. You need someone with a great eye and attention to detail to do that work. And that's a little bit easier to find than a strategic creative director and less expensive too. So it makes sense to bring that work in house. And then you still need that creative thinking and that strategy to help move things where you want it to go.", "token_estimate": 740, "speakers": ["Dave Taylor"], "start_timestamp": "21:54", "end_timestamp": "21:54", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "ee4350ac-118b-45ea-b155-8a5eeea8223d", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 10, "content": "Cole Heilborn (25:07): Sure. So you've described a lot of the pros. I'm curious, what are some the challenges lie underneath the surface of this model?\n\nDave Taylor (25:20): The downside of it is there are some days where you just don't want to do it, and there's no one to hand something off to you, and the pressure is real to ensure that your supported clients the way that you need to so that they call back for the next project, or when they leave that brand, they move on. The challenge is when you're going up against a larger agency, some people just don't trust that you're going to be able to pull that kind of work together, even with five plus years of quality work, that makes a difference in references from those clients. So that's definitely a challenge as well. But what really lies under the surface is sometimes it's Thursday and you've been grinding away and you've been really busy and you just want to talk to somebody at the water cooler. And over the last couple of years, that's been really difficult. And as things are opening up a little bit more, at least here in Seattle, and starting to feel a little bit more safe, kind of getting back to that rhythm of, oh, meeting people for coffee or having a beer at the end of the day. And that totally changes the outlook from being solo in the office.\n\nCole Heilborn (26:37): Sure. Yeah. Oh dude, that can be brutal. That mental health, when you're just isolated jamming away and video calls are great, and maybe you've got a Slack channel going on with your editor, but it doesn't replace the water cooler chat.\n\nDave Taylor (26:54): No, no. The 15 minutes of BSing in the morning while you're getting the coffee and fist bumping and making fun of each other. That happens in an agency in the morning. You do kind of miss that. And before I got my new studio space the last couple of years, I was working out of coworking space and there was a number of other small businesses working in there. So I had a little bit of that then, and I really enjoyed that. But having this kind of dedicated space is pretty sweet. That's also one of the reasons why I want to bring on some folks.", "token_estimate": 539, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "25:07", "end_timestamp": "26:54", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "5c2fd078-6df0-467e-8ac1-682d5afdcc46", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 11, "content": "Cole Heilborn (27:31): How do you handle capacity? Because you're one person, and I realize a lot of the work that you guys do, you have other people helping out with it, but you're still kind of the final gatekeeper for a lot of stuff. And that comes at a cost when you only have so much time and time, sometimes not often equates to so much money. How do you manage that?\n\nDave Taylor (27:58): I think that goes back to having an overhead conversation because I have the power to be able to say no when it makes sense. And being smart about the work that you bring into the studio and the types of clients that you're working with. I purposely don't pursue clients or work with collaborators that I know whose hair is constantly on fire. The Diamondback Project, for example, that had a really wonderful long tail to it. And so being able to do things in the right way where your hair's not on fire on a consistent basis really allows you to work in a way where the work is better, your hair's not on fire, your capacity is manageable. There's ups and downs and things do come through, and we do help out clients when they need something in a pinch. But in general, you just have to be smart about what you say yes or no. (28:59): And knowing that you have a deep bench that you could work with. But sometimes one of my greatest joys sometimes in this business is saying no to something because I'm too busy and handing it off to a trusted collaborator or friend who then goes and crushes it and creates another great relationship because I feel like there's a lot of room at the table and everyone can eat. And I love sharing. My plate is full. There's no need to gorge. And when you're doing things the right way and you're managing your finances in a way that makes sense, and with my little office here, I totally could have dropped $6,000 on a sweet build out with bookcases and all the things, but I got my couches from an office that closed that I got for 70 bucks. It's super sweet. And then my desk is made out of a door and sawhorses. (29:55): And so it's like, but where I spend my money is on is I take vacations that have nice bikes and then my computer and everything else that I work with is completely dialed where it makes sense to spend money. And my accountant is a place that makes sense to spend money. And the amount of bandwidth that I get from having that part of my world handled for me opens up a ton of capacity where I could just earn more money. So it's having an understanding of where you spend your time that's going to be profitable, where you're going to spend your time that's going to be personally mentally profitable, and then where you're going to spend your money that's going to aid those two things to happen.", "token_estimate": 689, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "27:31", "end_timestamp": "27:58", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "6701f5ef-938c-4e47-8601-48153fe40b58", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 12, "content": "Cole Heilborn (30:41): Clients sometimes look at a solopreneur like yourself, and then they look at, I'm going to use a polar opposite, like a Widen and Kennedy. And they're like, why would we trust the small team or the solo person with a job that why trust someone who's doing it by themselves when you could have this full suite of people who are at your beck and call?\n\nDave Taylor (31:08): Well, I think one, there's a scale conversation there. And why didn't Kenny does hire, I mean, not wide. Nike for example, customer mentioned Wide does hire a lot of solo people to do projects, whether it's design or t-shirt designs, et cetera. But as far as a ginormous global brand campaign around the Olympics, sure, myself and my collaborators, maybe we could come up with this just as great of an idea, but then how are we going to execute $300 million worth of media spend? That doesn't make sense. But what it comes down to really is do I trust this person I'm talking to execute what my hopes and dreams for this campaign or this work is going to do? Because when that person calls White End Kennedy, they're still talking to one or two people, and are they going to be, is that client going to be able to trust that those two creative directors that they're talking to at the time? And that's really what it comes down to. (32:14): Is it a relationship that's going to work between the people that are on the phone making the decisions, is what it really comes down to. And just about anything that you do in business ideas or ideas. And they could come from anywhere. And a lot of my work comes from referrals. Oh, you should check out, ok bro, they did a great job on this project for us. And then Magic comes into the email machine. And then next thing you know, we're off on a new journey with a new brand and a new client executing work that we've never done before. And that gets really fun because for myself is if I get a referral, I want to do extra better for that person that referred me because your reputation is everything. And if you blow it and for whatever reason, you're not just losing that client that you're working on, you're also losing the client that referred you to them. They don't want to look bad either. And so it is this virtuous cycle of trying to be successful and building relationships how the network really grows and people give you phone calls.", "token_estimate": 597, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "30:41", "end_timestamp": "31:08", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "2e8eefd6-d671-43a8-9220-da828743c6a4", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 13, "content": "Cole Heilborn (33:22): So yeah, that kind of leads me to my next question. How do you manage all the different things that you have to do on a daily basis, whether it's project related, business admins, sales, marketing, one of the benefits of having multiple people on your team is that you can divvy up some of those daily or weekly tasks.\n\nDave Taylor (33:41): I have a whiteboard that gets updated every morning with little boxes next to each line item that needs to get done. And I just keep it as simple as possible, and it goes down to who am I going to call to help with a piece of that work that needs to be done. And then following up with that person through that process also ends up on that whiteboard. And so it becomes a very visual thing. I don't love managing stuff digitally because I feel like it just gets lost amongst the 75 other tabs I have open at a time, so when I can keep things, I'm looking at my whiteboard right now when I keep things up on that whiteboard and my chicken scratch, I know it's legit needs to happen. So whiteboards, notebooks with notes, et cetera is how everything gets done. And I have personal almost to a fault, and being on time is a big part of that as well. I drives my wife crazy, perpetually five minutes late. I'm perpetually about 10 minutes early. So I kind of pride myself on that. And every once in a while, a calendar invite will get a little wonky for whatever reason. Oh man, it gives me a heart attack.\n\nCole Heilborn (35:03): The good old whiteboard man, they sometimes just can't be beat.\n\nDave Taylor (35:07): Mine's on wheels, so it's actually special.\n\nCole Heilborn (35:09): Oh, that's cool. That's pretty special. How do small shops influence big agencies, or why do big agencies need small agencies in the same ecosystem to exist or to thrive?", "token_estimate": 454, "speakers": ["Cole Heilborn", "Dave Taylor"], "start_timestamp": "33:22", "end_timestamp": "35:09", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}, {"id": "42434a45-5a1a-4634-9902-b8bd5fdb656c", "episode_id": "bfc69f3c-6275-4768-b7c0-5190cd0326e5", "cms_item_id": "68225dfc7bb476527f8c486e", "chunk_index": 14, "content": "Dave Taylor (35:23): Because I think small brands become big brands and because ideas and the resourcefulness that come out of smaller agencies help bigger agencies see broader picture because not every project that they're going to do at a big agency is going to have a million dollar production budget to go make an amazing video. They still need to roll up their sleeves and get their hands dirty and understand how to do something for 20,000 bucks because you never know that small activation might be the thing that triggers a big wellspring of goodwill to your brand. And so I think from that perspective, that helps big agencies. And then from the other perspective, understanding how big agencies do their strategy and their market research and things like that. And the people that are constantly getting, especially senior level people that are getting jettisoned or pulling the escape hatch out of that big agency world and wanting to do work that they care about and are a fan of, they look to smaller agencies to partner with. And so I've been lucky because I have had big agency experience and big in-house brand experience that my network is the senior level people that have worked at a really high level. And so we can bring that level of thinking that a Nike is getting into a small brand like Diamondback or even a brand like Specialized, which is four or five times the size of Diamondback, but still not at the level of a Nike, but still getting that thinking into a brand that is really valuable.\n\nCole Heilborn (37:08): So something we talked about in our introduction call was this idea of being a fan versus a cynic. And I feel like you introduced me to this concept, and I feel like after listening to you describe just some of these points in our call today, I have a better understanding of how you see those two. But I'm curious if you could break down a fan versus a cynic for the audience, and then I want to dive a little deeper into that.", "token_estimate": 493, "speakers": ["Dave Taylor", "Cole Heilborn"], "start_timestamp": "35:23", "end_timestamp": "37:08", "podcast_index": 71, "episode_name": "EP 71: Dave Taylor | Be a Fan, Not a Cynic | Okaybro", "slug": "ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "web_url": "https://www.portsidepro.com/podcast-feed/ep-71-dave-taylor-be-a-fan-not-a-cynic-okaybro", "guest_name": "Dave Taylor", "guest_title": "Okaybro", "categories": [], "short_description": "Pros and cons of being a solo creative entrepreneur.", "podcast_length": "47:00"}]
